    #[test]
    fn quantized_lifecycle_waits_for_real_admission_and_preserves_source() {
        use action_correlation::{ActionDisposition, ActionSourceClass};
        use creative_mutation::CreativeMutationOrigin;
        use web::state::WebAction;

        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state.clone());
        app.recovery_writer = None;
        app.performance_recording = true;
        let sequencer = web_state.action_sequencer();

        let eligible = sequencer.envelope(
            ActionSourceClass::Phone,
            WebAction::Quantized {
                inner: Box::new(WebAction::SetParam {
                    param: "brightness".into(),
                    value: serde_json::json!(0.4),
                }),
            },
        );
        app.apply_correlated_action(eligible, |app, action| {
            app.handle_web_action_from_origin(action, ActionSourceClass::Phone)
        });
        assert_eq!(app.highest_applied_action_sequence, 0);
        assert_eq!(app.quantized_actions.len(), 1);
        assert_eq!(app.quantized_action_sources, vec![ActionSourceClass::Phone]);
        assert_eq!(
            web_state
                .action_receipts_for_test()
                .last()
                .unwrap()
                .disposition,
            ActionDisposition::Quantized
        );

        let prohibited = sequencer.envelope(
            ActionSourceClass::Native,
            WebAction::Quantized {
                inner: Box::new(WebAction::BendPad {
                    index: 0,
                    held: true,
                }),
            },
        );
        app.apply_correlated_action(prohibited, |app, action| {
            app.handle_web_action_from_origin(action, ActionSourceClass::Native)
        });
        assert_eq!(
            web_state
                .action_receipts_for_test()
                .last()
                .unwrap()
                .disposition,
            ActionDisposition::Refused
        );

        app.quantized_bar = Some(0);
        app.mod_matrix.current_beat = 4.0;
        app.release_quantized_actions_on_downbeat();
        assert!(app.quantized_actions.is_empty());
        assert!(app.quantized_action_sources.is_empty());
        assert_eq!(app.pending_performance_edits.len(), 1);
        assert_eq!(
            app.pending_performance_edits[0].origin(),
            CreativeMutationOrigin::Phone
        );

        let immediate = sequencer.envelope(
            ActionSourceClass::Phone,
            WebAction::Quantized {
                inner: Box::new(WebAction::SetBlackout { enabled: true }),
            },
        );
        let immediate_sequence = immediate.sequence().get();
        app.apply_correlated_action(immediate, |app, action| {
            app.handle_web_action_from_origin(action, ActionSourceClass::Phone)
        });
        assert!(app.blackout);
        assert_eq!(app.highest_applied_action_sequence, immediate_sequence);

        app.clear_quantized_actions();
        for _ in 0..256 {
            app.quantized_actions.push(WebAction::MorphCapture {
                slot: "a".into(),
                stack_revision: Some(app.layer_stack_revision),
                composition_revision: Some(app.composition_revision),
            });
        }
        let over_cap = sequencer.envelope(
            ActionSourceClass::Browser,
            WebAction::Quantized {
                inner: Box::new(WebAction::SetParam {
                    param: "contrast".into(),
                    value: serde_json::json!(0.5),
                }),
            },
        );
        let before_high_water = app.highest_applied_action_sequence;
        app.apply_correlated_action(over_cap, |app, action| {
            app.handle_web_action_from_origin(action, ActionSourceClass::Browser)
        });
        assert_eq!(app.quantized_actions.len(), 256);
        assert_eq!(app.highest_applied_action_sequence, before_high_water);
        assert_eq!(
            web_state
                .action_receipts_for_test()
                .last()
                .unwrap()
                .disposition,
            ActionDisposition::Refused
        );
    }

    #[test]
    fn audience_latch_uses_the_immutable_frame_sequence_and_records_once() {
        use action_correlation::{ActionDisposition, ActionSourceClass};
        use std::time::Duration;

        let web_state = WebState::new().expect("test token");
        let sequencer = web_state.action_sequencer();
        let origin = Instant::now();
        let first = sequencer.envelope_at(ActionSourceClass::Browser, origin, ());
        assert!(web_state.record_action_apply(&first, origin + Duration::from_millis(3)));
        let mut latch = AudienceActionSubmissionLatch::new(first.sequence().get(), 77);
        let second = sequencer.envelope_at(
            ActionSourceClass::Native,
            origin + Duration::from_millis(4),
            (),
        );
        assert!(web_state.record_action_apply(&second, origin + Duration::from_millis(5)));

        assert!(!latch.record_presented(&web_state, true));
        assert!(!latch.capture_audience_submit(false, origin + Duration::from_millis(7)));
        assert!(web_state.action_receipts_for_test().is_empty());
        let submitted_at = origin + Duration::from_millis(11);
        assert!(latch.capture_audience_submit(true, submitted_at));
        assert!(!latch.capture_audience_submit(true, origin + Duration::from_millis(31)));
        assert!(!latch.record_presented(&web_state, false));
        assert!(
            web_state.action_receipts_for_test().is_empty(),
            "a later audience surface failure cannot claim Presented",
        );
        // Confirmation deliberately happens much later. The resulting metric
        // must stay anchored to the captured queue-submit seam (11 - 3 ms),
        // never to this post-present confirmation time.
        assert!(latch.record_presented(&web_state, true));
        assert!(!latch.record_presented(&web_state, true));

        let receipts = web_state.action_receipts_for_test();
        assert_eq!(receipts.len(), 1);
        assert_eq!(receipts[0].sequence, first.sequence());
        assert_eq!(receipts[0].disposition, ActionDisposition::Presented);
        assert_eq!(receipts[0].submission_generation, Some(77));
        assert_eq!(receipts[0].apply_to_submit_us, Some(8_000));
        let snapshot = web_state.action_timing_snapshot();
        assert_eq!(snapshot.apply_to_submit.p50_us, 8_000);
        assert_eq!(snapshot.last_presented_sequence, first.sequence().get());
        assert_eq!(snapshot.last_submission_generation, 77);
        assert_eq!(snapshot.pending, 1, "post-evaluation action stays pending");
    }

    #[test]
    fn yaml_identity_is_minted_before_mutation_and_noop_is_refused() {
        use action_correlation::{ActionDisposition, ActionSourceClass};
        use patch::editor::EditorHistoryBoundary;

        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state.clone());
        app.recovery_writer = None;
        let before = app.history_checkpoint("Native", "native_editor").unwrap();
        let identity = app.mint_native_action_identity();
        app.apply_native_history_boundaries(
            vec![EditorHistoryBoundary::Begin {
                gesture_id: 17,
                label: "Native".into(),
                category: "native_editor".into(),
            }],
            Some(before),
            Some(identity),
        );
        app.master_effects.brightness = 0.75;
        app.apply_native_history_boundaries(
            vec![EditorHistoryBoundary::End { gesture_id: 17 }],
            None,
            None,
        );
        assert_eq!(
            app.highest_applied_action_sequence,
            identity.sequence().get()
        );
        assert_eq!(web_state.action_timing_snapshot().pending, 1);

        let before = app
            .history_checkpoint("Native noop", "native_editor")
            .unwrap();
        let noop = app.mint_native_action_identity();
        app.apply_native_history_boundaries(
            vec![EditorHistoryBoundary::Begin {
                gesture_id: 18,
                label: "Native noop".into(),
                category: "native_editor".into(),
            }],
            Some(before),
            Some(noop),
        );
        app.apply_native_history_boundaries(
            vec![EditorHistoryBoundary::End { gesture_id: 18 }],
            None,
            None,
        );
        assert_eq!(
            app.highest_applied_action_sequence,
            identity.sequence().get()
        );
        let receipt = web_state
            .action_receipts_for_test()
            .last()
            .copied()
            .unwrap();
        assert_eq!(receipt.sequence, noop.sequence());
        assert_eq!(receipt.source, ActionSourceClass::Native);
        assert_eq!(receipt.disposition, ActionDisposition::Refused);
    }

    #[test]
    fn native_editor_keyboard_start_and_idle_frames_do_zero_spurious_work() {
        let pointer = egui::Event::PointerButton {
            pos: egui::pos2(8.0, 8.0),
            button: egui::PointerButton::Primary,
            pressed: true,
            modifiers: egui::Modifiers::default(),
        };
        let key = egui::Event::Key {
            key: egui::Key::Enter,
            physical_key: Some(egui::Key::Enter),
            pressed: true,
            repeat: false,
            modifiers: egui::Modifiers::default(),
        };
        assert!(native_editor_has_ingress_candidate(
            true,
            false,
            false,
            std::slice::from_ref(&pointer),
        ));
        assert!(native_editor_has_ingress_candidate(
            true,
            false,
            false,
            std::slice::from_ref(&key),
        ));
        assert!(
            !native_editor_has_ingress_candidate(true, true, false, std::slice::from_ref(&key),),
            "later keys stay inside the identity which opened the edit",
        );
        assert!(!native_editor_has_ingress_candidate(
            true,
            false,
            true,
            std::slice::from_ref(&key),
        ));
        assert!(!native_editor_has_ingress_candidate(
            true,
            false,
            false,
            &[],
        ));
        assert!(!native_editor_history_work_required(false, false, false));
        assert!(native_editor_history_work_required(true, false, false));
        assert!(native_editor_history_work_required(false, true, false));

        let sequencer = action_correlation::ActionSequencer::default();
        let idle_identity = native_editor_has_ingress_candidate(true, false, false, &[])
            .then(|| sequencer.envelope(action_correlation::ActionSourceClass::Native, ()));
        assert!(idle_identity.is_none());
        assert_eq!(
            sequencer
                .envelope(action_correlation::ActionSourceClass::Browser, ())
                .sequence()
                .get(),
            1,
            "an idle editor frame mints no identity",
        );
    }

    #[test]
    fn video_decode_worker_flight_fact_is_bounded_and_reports_real_mailbox_state() {
        use flight_recorder::{WorkerKind, WorkerState};

        let stopped = flight_video_decode_worker_fact(std::iter::empty());
        assert_eq!(stopped.worker, WorkerKind::VideoDecode);
        assert_eq!(stopped.state, WorkerState::Stopped);
        assert_eq!(stopped.queue_capacity, 0);

        let ready = flight_video_decode_worker_fact([(
            false,
            Some(video::threaded::DecoderTelemetry::default()),
        )]);
        assert_eq!(ready.state, WorkerState::Ready);
        assert_eq!(ready.queue_depth, 0);
        assert_eq!(ready.queue_capacity, 2);

        let busy_telemetry = video::threaded::DecoderTelemetry {
            pending_command_depth: 1,
            accepted_uploads: 7,
            command_drops: 2,
            frame_overwrites: 3,
            stale_commands: 5,
            failed_decode_attempts: 11,
            ..video::threaded::DecoderTelemetry::default()
        };
        let busy = flight_video_decode_worker_fact([(false, Some(busy_telemetry))]);
        assert_eq!(busy.state, WorkerState::Busy);
        assert_eq!(busy.queue_depth, 1);
        assert_eq!(busy.completed_jobs, 7);
        assert_eq!(busy.dropped_jobs, 21);

        let full_telemetry = video::threaded::DecoderTelemetry {
            pending_command_depth: 1,
            pending_frames: 1,
            ..video::threaded::DecoderTelemetry::default()
        };
        let backpressured = flight_video_decode_worker_fact([(false, Some(full_telemetry))]);
        assert_eq!(backpressured.state, WorkerState::Backpressured);
        assert_eq!(backpressured.queue_depth, 2);
        assert_eq!(backpressured.queue_capacity, 2);

        let starting = flight_video_decode_worker_fact([(false, None)]);
        assert_eq!(starting.state, WorkerState::Starting);
        let failed = flight_video_decode_worker_fact([(
            true,
            Some(video::threaded::DecoderTelemetry::default()),
        )]);
        assert_eq!(failed.state, WorkerState::Failed);
    }

    #[test]
    fn gizmo_boundaries_coalesce_and_escape_keeps_its_pre_mutation_identity() {
        use action_correlation::{ActionDisposition, ActionSourceClass};

        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state.clone());
        app.recovery_writer = None;
        app.selected_layer = None;
        let sequencer = web_state.action_sequencer();
        let grab = gizmo_move_handle(&app);

        let begin = sequencer.envelope(
            ActionSourceClass::Native,
            transform_gizmo::GizmoPointerEvent {
                phase: transform_gizmo::GizmoPhase::Begin,
                output_uv: grab,
                modifiers: transform_gizmo::GizmoModifiers::NONE,
            },
        );
        app.apply_correlated_action(begin, |app, event| WebActionDispatchOutcome {
            batch: WebActionBatchDisposition::Continue,
            lifecycle: app.apply_transform_gizmo_event(event),
        });
        assert_eq!(
            web_state
                .action_receipts_for_test()
                .last()
                .unwrap()
                .disposition,
            ActionDisposition::Coalesced,
        );
        assert_eq!(app.highest_applied_action_sequence, 0);

        let moved = sequencer.envelope(
            ActionSourceClass::Native,
            transform_gizmo::GizmoPointerEvent {
                phase: transform_gizmo::GizmoPhase::Move,
                output_uv: [grab[0] + 0.1, grab[1]],
                modifiers: transform_gizmo::GizmoModifiers::NONE,
            },
        );
        let moved_sequence = moved.sequence().get();
        app.apply_correlated_action(moved, |app, event| WebActionDispatchOutcome {
            batch: WebActionBatchDisposition::Continue,
            lifecycle: app.apply_transform_gizmo_event(event),
        });
        assert_eq!(app.highest_applied_action_sequence, moved_sequence);

        let escape_identity = app.mint_native_action_identity();
        let escape_sequence = escape_identity.sequence().get();
        let lifecycle = app
            .transform_gizmo_escape()
            .expect("the committed drag consumes Escape");
        assert_eq!(lifecycle, ActionLifecycleOutcome::Applied);
        app.record_action_lifecycle_outcome(escape_identity, lifecycle);
        assert_eq!(app.highest_applied_action_sequence, escape_sequence);
        web_state.record_action_submission(escape_sequence, 1, Instant::now());
        let receipts = web_state.action_receipts_for_test();
        let receipt = receipts.last().unwrap();
        assert_eq!(receipt.sequence.get(), escape_sequence);
        assert_eq!(receipt.source, ActionSourceClass::Native);
        assert_eq!(receipt.disposition, ActionDisposition::Presented);
        assert!(app.transform_gizmo_drag.is_none());

        for phase in [
            transform_gizmo::GizmoPhase::Begin,
            transform_gizmo::GizmoPhase::End,
        ] {
            let boundary = sequencer.envelope(
                ActionSourceClass::Native,
                transform_gizmo::GizmoPointerEvent {
                    phase,
                    output_uv: gizmo_move_handle(&app),
                    modifiers: transform_gizmo::GizmoModifiers::NONE,
                },
            );
            app.apply_correlated_action(boundary, |app, event| WebActionDispatchOutcome {
                batch: WebActionBatchDisposition::Continue,
                lifecycle: app.apply_transform_gizmo_event(event),
            });
            assert_eq!(
                web_state
                    .action_receipts_for_test()
                    .last()
                    .unwrap()
                    .disposition,
                ActionDisposition::Coalesced,
            );
            assert_eq!(app.highest_applied_action_sequence, escape_sequence);
        }
    }

    #[test]
    fn stale_and_missing_disable_output_requests_and_controller_targets_are_refused() {
        use action_correlation::{ActionDisposition, ActionSourceClass};
        use controller_profile::{AutomationOrigin, AutomationValue, ControlParameter};

        assert_eq!(
            classify_output_display_request(Some(4), 5, true),
            OutputDisplayAdmission::StaleGeneration
        );
        assert_eq!(
            classify_output_display_request(Some(5), 5, false),
            OutputDisplayAdmission::MissingDisplay
        );
        let source = include_str!("main.rs");
        let request = source
            .split_once("fn apply_output_request(")
            .expect("output request applier")
            .1
            .split_once("fn apply_output_window_command(")
            .expect("bounded output request body")
            .0;
        let missing_arm = request
            .split_once("OutputDisplayAdmission::MissingDisplay => {")
            .expect("missing-display refusal arm")
            .1
            .split_once("if display_id != self.output_display_id")
            .expect("selection mutation follows admission")
            .0;
        assert!(missing_arm.contains("return OutputRequestOutcome::default()"));
        assert!(
            !missing_arm.contains("close_output_window"),
            "missing display + requested disable must refuse the whole fold before closing Output",
        );

        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state.clone());
        app.recovery_writer = None;
        let missing = stable_layer(999);
        for (source, origin) in [
            (ActionSourceClass::Midi, AutomationOrigin::Midi),
            (
                ActionSourceClass::Osc,
                AutomationOrigin::Osc(std::net::SocketAddr::from(([127, 0, 0, 1], 9000))),
            ),
        ] {
            let envelope = web_state.action_sequencer().envelope(
                source,
                (
                    origin,
                    controller_profile::RuntimeControlAddress::Layer {
                        layer_id: missing,
                        parameter: ControlParameter::Opacity,
                    },
                    AutomationValue::Absolute(0.5),
                ),
            );
            app.apply_correlated_action(envelope, |app, (origin, address, value)| {
                match app.apply_automation_control(origin, address, value) {
                    Ok(outcome) => WebActionDispatchOutcome {
                        batch: WebActionBatchDisposition::Continue,
                        lifecycle: outcome.lifecycle,
                    },
                    Err(_) => {
                        WebActionDispatchOutcome::refused(WebActionBatchDisposition::Continue)
                    }
                }
            });
        }
        assert_eq!(app.highest_applied_action_sequence, 0);
        let receipts = web_state.action_receipts_for_test();
        assert_eq!(receipts.len(), 2);
        assert!(receipts
            .iter()
            .all(|receipt| receipt.disposition == ActionDisposition::Refused));
    }

    #[test]
    fn repeated_controller_bend_and_value_actions_do_not_advance_high_water() {
        use action_correlation::{ActionDisposition, ActionSourceClass};
        use controller_profile::{
            AutomationOrigin, AutomationValue, ControlParameter, RuntimeControlAddress,
        };

        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state.clone());
        app.recovery_writer = None;
        let sequencer = web_state.action_sequencer();
        for (address, value, expected_applied) in [
            (
                RuntimeControlAddress::Master(ControlParameter::Bend1),
                AutomationValue::Gate(true),
                true,
            ),
            (
                RuntimeControlAddress::Master(ControlParameter::Bend1),
                AutomationValue::Gate(true),
                false,
            ),
            (
                RuntimeControlAddress::Master(ControlParameter::Bend1),
                AutomationValue::Gate(false),
                true,
            ),
            (
                RuntimeControlAddress::Master(ControlParameter::Bend1),
                AutomationValue::Gate(false),
                false,
            ),
            (
                RuntimeControlAddress::Master(ControlParameter::Brightness),
                AutomationValue::Absolute(0.5),
                false,
            ),
            (
                RuntimeControlAddress::Master(ControlParameter::Brightness),
                AutomationValue::Absolute(0.75),
                true,
            ),
            (
                RuntimeControlAddress::Master(ControlParameter::Brightness),
                AutomationValue::Absolute(0.75),
                false,
            ),
        ] {
            let before = app.highest_applied_action_sequence;
            let envelope = sequencer.envelope(
                ActionSourceClass::Midi,
                (AutomationOrigin::Midi, address, value),
            );
            let sequence = envelope.sequence().get();
            app.apply_correlated_action(envelope, |app, (origin, address, value)| {
                match app.apply_automation_control(origin, address, value) {
                    Ok(outcome) => WebActionDispatchOutcome {
                        batch: WebActionBatchDisposition::Continue,
                        lifecycle: outcome.lifecycle,
                    },
                    Err(_) => {
                        WebActionDispatchOutcome::refused(WebActionBatchDisposition::Continue)
                    }
                }
            });
            if expected_applied {
                assert_eq!(app.highest_applied_action_sequence, sequence);
            } else {
                assert_eq!(app.highest_applied_action_sequence, before);
                assert_eq!(
                    web_state
                        .action_receipts_for_test()
                        .last()
                        .unwrap()
                        .disposition,
                    ActionDisposition::Refused,
                );
            }
        }
    }

    fn stable_layer(value: u64) -> image_routing::StableLayerId {
        image_routing::StableLayerId::new(value).unwrap()
    }

    #[test]
    fn authored_bypass_capability_is_independent_of_final_program_vhs() {
        use visual_rack::{NodeId, RuntimeVisualNode, RuntimeVisualNodeKind, RuntimeVisualRack};

        let mixed = [(stable_layer(1), true), (stable_layer(2), false)];
        let mut canonical_then_global =
            RuntimeVisualRack::synthetic_legacy(LegacyRackScope::Master);
        canonical_then_global
            .push(RuntimeVisualNodeKind::Transform(
                spatial::SpatialTransform::default(),
            ))
            .unwrap();

        // A later global custom segment is compatible with canonical bypass.
        // VHS is a final-program stage and therefore adds no per-layer bypass
        // restriction, including for a mixed authored population.
        assert!(validate_master_bypass_capability(&canonical_then_global, &mixed).is_ok());

        let global_then_canonical = RuntimeVisualRack::try_from_parts(
            vec![
                RuntimeVisualNode::authored(
                    NodeId::new(3).unwrap(),
                    RuntimeVisualNodeKind::Transform(spatial::SpatialTransform::default()),
                ),
                RuntimeVisualNode::authored(
                    NodeId::LEGACY_CANONICAL,
                    RuntimeVisualNodeKind::LegacyCanonical,
                ),
                RuntimeVisualNode::authored(
                    NodeId::LEGACY_TEMPORAL,
                    RuntimeVisualNodeKind::LegacyTemporal,
                ),
            ],
            Some(4),
        )
        .unwrap();
        let error = validate_master_bypass_capability(&global_then_canonical, &mixed).unwrap_err();
        assert_eq!(
            error,
            evaluated_frame::evaluated_composition::CompositionPlanError::AmbiguousMasterBypass {
                layers: vec![stable_layer(1)],
            }
        );

        // No bypass capability means neither restriction applies.
        let inheriting = [(stable_layer(1), false), (stable_layer(2), false)];
        assert!(validate_master_bypass_capability(&global_then_canonical, &inheriting).is_ok());
    }

    #[test]
    fn procedural_motion_ingress_is_closed_and_classifies_its_impact() {
        let mut params = motion::MotionParams::default();
        // Every kind token is a topology edit: it changes which pass writes
        // the field and which bindings must be prepared.
        let impact = apply_motion_param(
            &mut params,
            true,
            "field_source",
            &serde_json::json!("procedural_weave"),
        )
        .unwrap();
        assert_eq!(impact, MotionEditImpact::MemoryTopology);
        assert_eq!(
            params.field_source,
            motion::MotionFieldSource::Procedural(motion::ProceduralFieldKind::Weave)
        );
        // The two scalars are ordinary coalescible values at both scopes.
        assert_eq!(
            apply_motion_param(&mut params, true, "field_scale", &serde_json::json!(0.9)).unwrap(),
            MotionEditImpact::ValuesOnly
        );
        assert_eq!(
            apply_motion_param(&mut params, false, "field_rate", &serde_json::json!(-1.25))
                .unwrap(),
            MotionEditImpact::ValuesOnly
        );
        assert_eq!(params.procedural.scale, 0.9);
        assert_eq!(params.procedural.rate, -1.25);
        // A bare "procedural" token names no kind and is refused, never
        // defaulted onto one; out-of-range scalars are refused, not clamped.
        assert!(apply_motion_param(
            &mut params,
            true,
            "field_source",
            &serde_json::json!("procedural")
        )
        .is_err());
        assert!(
            apply_motion_param(&mut params, true, "field_rate", &serde_json::json!(2.5)).is_err()
        );
        assert_eq!(params.procedural.rate, -1.25);
        // The four flow-shaping controls are likewise ordinary values, at
        // both scopes, refused (never clamped) out of range.
        for (param, value) in [
            ("stretch", 0.5),
            ("edge_repel", 0.25),
            ("vector_trash", 0.75),
            ("trash_block_size", 64.0),
        ] {
            assert_eq!(
                apply_motion_param(&mut params, true, param, &serde_json::json!(value)).unwrap(),
                MotionEditImpact::ValuesOnly,
                "{param}"
            );
        }
        assert_eq!(params.shaping.stretch, 0.5);
        assert_eq!(params.shaping.trash_block_size, 64.0);
        assert!(apply_motion_param(
            &mut params,
            false,
            "trash_block_size",
            &serde_json::json!(1.0)
        )
        .is_err());
    }

    #[test]
    #[ignore = "requires a GPU adapter"]
    fn live_motion_cache_does_not_alias_distinct_codec_payloads_with_equal_endpoints() {
        use evaluated_frame::evaluated_composition::{
            CompositionPlanInput, EvaluatedCompositionPlan, LayerMotionPlanInput,
            MotionCodecFrameFacts,
        };
        use motion::{
            CurvedShutterParams, MotionDeviceLimits, MotionFieldSource, MotionLatticeQuality,
            MotionParams,
        };
        use video::threaded::ReadyFrame;
        use video::{
            AdjacentReferencePolicy, CodecFrameIdentity, CodecMotionFrame, CodecMotionFrameType,
            CodecMotionProduct, CodecMotionProvenance, CodecMotionStatus, CodecPastReferenceProof,
            CodecTimeBase,
        };

        fn codec_product(motion_x: i32) -> CodecMotionProduct {
            CodecMotionFrame {
                source_dimensions: [1, 1],
                frame_delta_seconds: 1.0 / 30.0,
                source_generation: 7,
                frame_ordinal: 9,
                algorithm_version: motion::MOTION_ALGORITHM_VERSION,
                provenance: CodecMotionProvenance::FfmpegExportMvs,
                frame_type: CodecMotionFrameType::Predictive,
                status: CodecMotionStatus::Available,
                past_reference_proof: Some(CodecPastReferenceProof {
                    policy: AdjacentReferencePolicy::Mpeg4Part2SimpleProgressiveIp,
                    reference: CodecFrameIdentity {
                        source_generation: 7,
                        pts: 8,
                        presentation_ordinal: 8,
                    },
                    destination: CodecFrameIdentity {
                        source_generation: 7,
                        pts: 9,
                        presentation_ordinal: 9,
                    },
                    elapsed_ticks: 1,
                    time_base: CodecTimeBase::new(1, 30).unwrap(),
                }),
                vectors: vec![motion::CodecMotionVector {
                    destination: [0, 0],
                    block: [1, 1],
                    motion: [motion_x, 0],
                    motion_scale: 1,
                    seconds_from_reference: 1.0 / 30.0,
                    reference: motion::CodecReferenceDirection::Past,
                    visibility: 1.0,
                }],
            }
            .into()
        }

        fn ready(product: CodecMotionProduct) -> ReadyFrame {
            ReadyFrame {
                rgba: video::DecodedImagePayload::from_owned_rgba(vec![255, 0, 0, 255]),
                codec_motion: Some(product),
                loops_advanced: 0,
                source_generation: 7,
                pts: Some(9),
                codec_identity: None,
                source_seconds: 9.0 / 30.0,
                duration_seconds: 1.0,
            }
        }

        let instance = wgpu::Instance::default();
        let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            compatible_surface: None,
            force_fallback_adapter: false,
        }))
        .expect("GPU adapter for live motion cache regression");
        let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor {
            label: Some("Live Motion Cache Identity Test"),
            required_features: wgpu::Features::empty(),
            required_limits: wgpu::Limits::default(),
            ..Default::default()
        }))
        .expect("GPU device for live motion cache regression");

        let mut layer = Layer::new_spout_with_media_policy(
            "motion-cache-digest-regression",
            &device,
            &queue,
            &media_safety::MediaSafetyPolicy::safe(),
        )
        .unwrap();
        let layer_id = layer.stable_layer_id();
        let composition = legacy_runtime_composition(&[layer_id]).unwrap();
        let master_rack = RuntimeVisualRack::synthetic_legacy(LegacyRackScope::Master);
        let layer_racks = [(
            layer_id,
            RuntimeVisualRack::synthetic_legacy(LegacyRackScope::Layer),
        )];
        let effects = effects::EffectUniforms::default();
        let transform = spatial::SpatialTransform::default();
        let ntsc = ntsc::NtscParams::default();
        let temporal = effects::params::TemporalParams::default();
        let modulation = modulation::ModMatrix::new().frame(1);
        let evaluated = EvaluatedFramePlan::evaluate(
            &modulation,
            FramePlanContext::new(1, 1, 0.0),
            MasterFrameInput {
                effects: &effects,
                transform: &transform,
                ntsc: &ntsc,
                temporal: &temporal,
            },
            [LayerFrameInput {
                source: SourceTap::new(layer_id.get(), 0, 1, 1),
                effects: &effects,
                transform: &transform,
                opacity: 1.0,
                mosh_send: 1.0,
                speed: 1.0,
                fps: 30.0,
                blend_mode: layers::BlendMode::Normal,
                visible: true,
                paused: false,
                bypass_master_fx: false,
                bypass_temporal_fx: false,
                pattern: None,
            }],
        );
        let layer_motion = [LayerMotionPlanInput {
            stable_id: layer_id,
            params: MotionParams {
                field_source: MotionFieldSource::CodecVectors,
                lattice_quality: MotionLatticeQuality::Live,
                shutter: CurvedShutterParams {
                    angle_degrees: 180.0,
                    ..CurvedShutterParams::default()
                },
                ..MotionParams::default()
            },
            codec: MotionCodecFrameFacts {
                available: true,
                source_generation: 7,
                frame_ordinal: 9,
            },
        }];
        let mattes = [image_routing::LayerMatte::default()];
        let plan = evaluated
            .plan_composition(
                CompositionPlanInput::new(&composition, &master_rack, &layer_racks)
                    .with_layer_mattes(&mattes, false)
                    .with_motion(
                        MotionParams::default(),
                        &layer_motion,
                        MotionDeviceLimits::new(
                            device.limits().max_texture_dimension_2d,
                            device.limits().max_buffer_size,
                        ),
                    ),
            )
            .unwrap();
        let EvaluatedCompositionPlan::Advanced(plan) = plan else {
            panic!("active codec motion fixture delegated LegacyExact")
        };
        let motion_plan = plan.motion().advanced().unwrap();

        let first = codec_product(-1);
        let first_identity = first.exact_identity().unwrap();
        layer
            .upload_ready_media_frame(&device, &queue, 1, &mut ready(first))
            .unwrap();
        let mut cache = Vec::new();
        let (diagnostics, unavailable) =
            refresh_live_codec_motion_cache(std::slice::from_ref(&layer), motion_plan, &mut cache);
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        assert!(unavailable.is_empty());
        assert_eq!(cache.len(), 1);
        assert_eq!(cache[0].codec_identity, first_identity);
        assert!(cache[0].field.sample(0, 0).unwrap().velocity_uv_per_second[0] > 0.0);

        let second = codec_product(1);
        let second_identity = second.exact_identity().unwrap();
        assert_eq!(
            first_identity.first_reference,
            second_identity.first_reference
        );
        assert_eq!(
            first_identity.latest_destination,
            second_identity.latest_destination
        );
        assert_ne!(
            first_identity.content_sha256,
            second_identity.content_sha256
        );
        layer
            .upload_ready_media_frame(&device, &queue, 1, &mut ready(second))
            .unwrap();
        let (diagnostics, unavailable) =
            refresh_live_codec_motion_cache(std::slice::from_ref(&layer), motion_plan, &mut cache);
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        assert!(unavailable.is_empty());
        assert_eq!(cache.len(), 1);
        assert_eq!(cache[0].codec_identity, second_identity);
        assert!(cache[0].field.sample(0, 0).unwrap().velocity_uv_per_second[0] < 0.0);
    }

    #[test]
    fn m3_event_acceptance_rejected_exact_retains_events_and_manual_clear_holds() {
        use renderer::state::TemporalState;
        use temporal::{
            CollisionScoreParams, CollisionScoreTrigger, TemporalFrameAction, TemporalFrameEvents,
            TemporalFrameInput, TemporalFreezeState, TemporalResetCause,
        };
        use web::state::WebAction;

        // Pin the production rejection arm itself: the rejected creative pass
        // must not encode Temporal, flatten opaque output, clear slot 2, or
        // publish/dispose the held audience snapshot.
        let source = include_str!("main.rs").replace("\r\n", "\n");
        let exact_match = source
            .find("let mut legacy_render_result = renderer.render_evaluated_frame(")
            .expect("LegacyExact creative acceptance match");
        let exact_tail = &source[exact_match..];
        let rejection = exact_tail
            .find("// Slot 2 is the last accepted audience")
            .map(|start| &exact_tail[start..])
            .expect("documented rejection arm");
        let rejection = &rejection[..rejection
            .find("if temporal_frame_accepted")
            .expect("post-acceptance snapshot gate")];
        for forbidden in [
            "render_temporal_frame",
            "render_opaque_output",
            "clear_composite",
            "temporal_frame_accepted = true",
            "selective_hold_snapshot_valid = false",
        ] {
            assert!(
                !rejection.contains(forbidden),
                "rejected Exact arm unexpectedly contains {forbidden}"
            );
        }
        assert!(source
            .contains("if temporal_frame_accepted && temporal_input.freeze.program_advances()"));

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.temporal_params.originals.score = CollisionScoreParams {
            enabled: true,
            state_count: 8,
            trigger: CollisionScoreTrigger::Manual,
            ..CollisionScoreParams::default()
        };
        app.temporal_params.originals.garden.amount = 0.5;
        for _ in 0..3 {
            app.handle_web_action(WebAction::TriggerCollisionScore);
        }
        for _ in 0..2 {
            app.handle_web_action(WebAction::TriggerRefreshGarden);
        }
        assert_eq!(app.pending_temporal_events.manual_events, 3);
        assert_eq!(app.pending_temporal_events.garden_refresh_events, 2);

        let mut state = TemporalState::default();
        state.stage_frame(
            &app.temporal_params,
            TemporalFrameInput::new(
                1.0 / 30.0,
                TemporalFreezeState::Running,
                false,
                TemporalFrameEvents::default(),
            ),
            [64, 36],
        );
        state.commit_staged();
        let before_rejection = state.metrics();

        // Model the production Err arm: no Temporal call was encoded, hence no
        // staged transaction exists and the counted batch remains untouched.
        assert!(!state.has_staged_frame());
        assert_eq!(state.metrics(), before_rejection);
        assert_eq!(app.pending_temporal_events.manual_events, 3);
        assert_eq!(app.pending_temporal_events.garden_refresh_events, 2);

        // An accepted Program Freeze frame may maintain the held image but may
        // neither consume Score events nor release the pending batch.
        let frozen_input = TemporalFrameInput::new(
            1.0 / 30.0,
            TemporalFreezeState::ProgramFrozen,
            false,
            app.pending_temporal_events,
        );
        let frozen_plan = state.stage_frame(&app.temporal_params, frozen_input, [64, 36]);
        assert!(matches!(
            frozen_plan.action,
            TemporalFrameAction::HoldFrozenOutput
        ));
        assert_eq!(frozen_plan.score_events_consumed, 0);
        assert_eq!(frozen_plan.garden_refresh_events_consumed, 0);
        state.commit_staged();
        if frozen_input.freeze.program_advances() {
            app.pending_temporal_events = TemporalFrameEvents::default();
        }
        assert_eq!(state.metrics(), before_rejection);
        assert_eq!(app.pending_temporal_events.manual_events, 3);
        assert_eq!(app.pending_temporal_events.garden_refresh_events, 2);

        // The next accepted advancing frame consumes all three events exactly
        // once and only then releases the live pending batch.
        let accepted_input = TemporalFrameInput::new(
            1.0 / 30.0,
            TemporalFreezeState::Running,
            false,
            app.pending_temporal_events,
        );
        let accepted_plan = state.stage_frame(&app.temporal_params, accepted_input, [64, 36]);
        assert_eq!(accepted_plan.score_events_consumed, 3);
        assert_eq!(accepted_plan.garden_refresh_events_consumed, 2);
        assert!(accepted_plan.garden_force_refresh);
        state.commit_staged();
        if accepted_input.freeze.program_advances() {
            app.pending_temporal_events = TemporalFrameEvents::default();
        }
        assert_eq!(state.metrics().score_event_ordinal, 3);
        assert_eq!(app.pending_temporal_events, TemporalFrameEvents::default());

        // Trigger is saturating; Clear is domain-specific and preserves the
        // already materialized Program Freeze audience image.
        app.pending_temporal_events.manual_events = u32::MAX;
        app.pending_temporal_events.garden_refresh_events = u32::MAX;
        app.handle_web_action(WebAction::TriggerCollisionScore);
        app.handle_web_action(WebAction::TriggerRefreshGarden);
        assert_eq!(app.pending_temporal_events.manual_events, u32::MAX);
        assert_eq!(app.pending_temporal_events.garden_refresh_events, u32::MAX);
        let held_before_clear = state.metrics().freeze_hold_valid;
        assert!(held_before_clear);
        state.reset_for(TemporalResetCause::ManualClear);
        app.handle_web_action(WebAction::ClearTemporalMemory);
        let cleared = state.metrics();
        assert_eq!(cleared.history_valid, 0);
        assert!(!cleared.carrier_valid);
        assert_eq!(cleared.score_event_ordinal, 0);
        assert_eq!(cleared.score_state, 0);
        assert_eq!(cleared.freeze_hold_valid, held_before_clear);
        assert_eq!(cleared.last_reset, Some(TemporalResetCause::ManualClear));
        assert_eq!(app.pending_temporal_events, TemporalFrameEvents::default());
        assert_eq!(app.selective_temporal_debt, 0.0);
    }

    fn legacy_look_scope(
        mapped_layer_ids: Vec<u64>,
        applied_ntsc: bool,
        applied_temporal: bool,
    ) -> AppliedLookScope {
        AppliedLookScope {
            mapped_layer_ids,
            applied_ntsc,
            applied_temporal,
            applied_nodes: Vec::new(),
            applied_group_ids: Vec::new(),
            applied_bus_crossfade: false,
        }
    }

    fn runtime_group(
        value: u64,
        members: &[image_routing::StableLayerId],
    ) -> composition::RuntimeGroup {
        composition::RuntimeGroup {
            id: visual_rack::GroupId::new(value).unwrap(),
            name: composition::GroupName::new(format!("Group {value}")).unwrap(),
            members: composition::RuntimeGroupMembers::try_from_vec(members.to_vec()).unwrap(),
            opacity: 1.0,
            transform: spatial::SpatialTransform::default(),
            rack: RuntimeVisualRack::empty(),
            matte: None,
            solo: false,
            bypass: false,
            bus: composition::BusAssignment::Program,
        }
    }

    fn push_image_mask(
        rack: &mut RuntimeVisualRack,
        source: visual_rack::ResolvedImageSource,
    ) -> visual_rack::NodeId {
        rack.push(visual_rack::RuntimeVisualNodeKind::Mask(
            visual_rack::RuntimeMaskParams::Image(visual_rack::RuntimeImageMatte {
                tap: visual_rack::ResolvedImageTap {
                    source,
                    timing: visual_rack::EdgeTiming::CurrentFrame,
                },
                channel: visual_rack::MatteChannel::Alpha,
                invert: false,
                amount: 1.0,
                threshold: 0.5,
                softness: 0.1,
            }),
        ))
        .unwrap()
    }

    #[test]
    fn legacy_runtime_composition_inverts_app_front_order_exactly() {
        for ids in [
            Vec::new(),
            vec![stable_layer(1)],
            vec![stable_layer(1), stable_layer(2), stable_layer(3)],
        ] {
            let composition = legacy_runtime_composition(&ids).unwrap();
            assert_eq!(
                runtime_composition_front_to_back(&composition).unwrap(),
                ids
            );
            let root_ids: Vec<_> = composition
                .root()
                .iter()
                .map(|item| match *item {
                    composition::RuntimeRootItem::Layer { layer_id, .. } => layer_id,
                    composition::RuntimeRootItem::Group { .. } => {
                        panic!("legacy composition cannot synthesize a group")
                    }
                })
                .collect();
            assert_eq!(
                root_ids,
                ids.iter().rev().copied().collect::<Vec<_>>(),
                "runtime root is back-to-front"
            );
        }
    }

    #[test]
    fn staged_add_move_remove_preserve_stable_ids_and_exact_flat_order() {
        let one = stable_layer(11);
        let two = stable_layer(22);
        let three = stable_layer(33);
        let four = stable_layer(44);
        let initial = vec![one, two, three];
        let composition = legacy_runtime_composition(&initial).unwrap();

        let added = stage_composition_insert_ungrouped(&composition, &initial, four, initial.len())
            .unwrap();
        assert_eq!(
            runtime_composition_front_to_back(&added).unwrap(),
            [one, two, three, four]
        );

        let moved_order = [three, one, two, four];
        let moved = stage_composition_reorder(&added, &moved_order).unwrap();
        assert_eq!(
            runtime_composition_front_to_back(&moved).unwrap(),
            moved_order
        );

        let removed = stage_composition_remove(&moved, &moved_order, one).unwrap();
        assert_eq!(
            runtime_composition_front_to_back(&removed).unwrap(),
            [three, two, four]
        );
        assert_eq!(
            removed
                .flatten()
                .unwrap()
                .layers
                .iter()
                .map(|layer| layer.layer_id.get())
                .collect::<std::collections::BTreeSet<_>>(),
            [22, 33, 44].into_iter().collect()
        );
    }

    #[test]
    fn group_create_and_membership_canonicalize_browser_order_without_restacking() {
        let top = stable_layer(11);
        let middle = stable_layer(22);
        let bottom = stable_layer(33);
        let initial_front_to_back = vec![top, middle, bottom];
        let composition = legacy_runtime_composition(&initial_front_to_back).unwrap();

        // The browser sends selected rows front-to-back and defaults the root
        // insertion to the end. Non-empty grouping instead collapses the
        // selected run in place and stores members back-to-front.
        let (grouped, group_id) = stage_create_composition_group(
            &composition,
            composition::GroupName::new("Run").unwrap(),
            vec![middle, bottom],
            composition.root().len(),
        )
        .unwrap();
        assert_eq!(
            runtime_composition_front_to_back(&grouped).unwrap(),
            initial_front_to_back
        );
        assert_eq!(
            grouped
                .group(group_id)
                .unwrap()
                .members
                .iter()
                .collect::<Vec<_>>(),
            [bottom, middle]
        );

        // Membership input order is likewise only a set. Expanding the same
        // contiguous run to include the adjacent top layer keeps all three
        // visual positions unchanged.
        let expanded =
            stage_set_composition_group_members(&grouped, group_id, vec![top, middle, bottom])
                .unwrap();
        assert_eq!(
            runtime_composition_front_to_back(&expanded).unwrap(),
            initial_front_to_back
        );
        assert_eq!(
            expanded
                .group(group_id)
                .unwrap()
                .members
                .iter()
                .collect::<Vec<_>>(),
            [bottom, middle, top]
        );
    }

    #[test]
    fn grouping_preserves_one_bus_and_rejects_mixed_or_mismatched_admission() {
        let top = stable_layer(11);
        let middle = stable_layer(22);
        let bottom = stable_layer(33);
        let base = legacy_runtime_composition(&[top, middle, bottom]).unwrap();
        let selected_b =
            stage_set_composition_layer_bus(&base, middle, composition::BusAssignment::B)
                .unwrap()
                .unwrap();
        let selected_b =
            stage_set_composition_layer_bus(&selected_b, bottom, composition::BusAssignment::B)
                .unwrap()
                .unwrap();

        let (grouped, group_id) = stage_create_composition_group(
            &selected_b,
            composition::GroupName::new("B run").unwrap(),
            vec![middle, bottom],
            selected_b.root().len(),
        )
        .unwrap();
        assert_eq!(
            grouped.group(group_id).unwrap().bus,
            composition::BusAssignment::B
        );
        assert_eq!(
            runtime_composition_front_to_back(&grouped).unwrap(),
            [top, middle, bottom]
        );

        let shrunk = stage_set_composition_group_members(&grouped, group_id, vec![bottom]).unwrap();
        assert!(shrunk.root().iter().any(|item| matches!(
            item,
            composition::RuntimeRootItem::Layer {
                layer_id,
                bus: composition::BusAssignment::B
            } if *layer_id == middle
        )));
        assert_eq!(
            shrunk.group(group_id).unwrap().bus,
            composition::BusAssignment::B
        );

        let mixed = stage_set_composition_layer_bus(&base, middle, composition::BusAssignment::A)
            .unwrap()
            .unwrap();
        let before = mixed.clone();
        assert!(stage_create_composition_group(
            &mixed,
            composition::GroupName::new("mixed").unwrap(),
            vec![middle, bottom],
            mixed.root().len(),
        )
        .unwrap_err()
        .contains("share one"));
        assert_eq!(mixed, before);

        // A direct Program layer cannot be smuggled into the retained B bus.
        let direct_program = stage_set_composition_group_members(&grouped, group_id, vec![top]);
        assert!(direct_program.unwrap_err().contains("must remain"));
        assert_eq!(
            grouped
                .group(group_id)
                .unwrap()
                .members
                .iter()
                .collect::<Vec<_>>(),
            [bottom, middle]
        );
    }

    #[test]
    fn discontiguous_group_create_is_rejected_without_mutating_the_tree() {
        let top = stable_layer(11);
        let middle = stable_layer(22);
        let bottom = stable_layer(33);
        let composition = legacy_runtime_composition(&[top, middle, bottom]).unwrap();
        let before = composition.clone();

        let error = stage_create_composition_group(
            &composition,
            composition::GroupName::new("Split").unwrap(),
            vec![top, bottom],
            composition.root().len(),
        )
        .unwrap_err();

        assert!(error.contains("contiguous"));
        assert_eq!(composition, before);
    }

    #[test]
    fn deleting_group_stages_base_matte_tombstone_atomically_and_never_retargets() {
        let layer_id = stable_layer(11);
        let removed = visual_rack::GroupId::new(7).unwrap();
        let replacement = visual_rack::GroupId::new(8).unwrap();
        let composition = composition::RuntimeComposition::try_from_parts(
            vec![runtime_group(removed.get(), &[])],
            vec![
                composition::RuntimeRootItem::Group { group_id: removed },
                composition::RuntimeRootItem::Layer {
                    layer_id,
                    bus: composition::BusAssignment::Program,
                },
            ],
            Some(replacement.get()),
            0.5,
        )
        .unwrap();
        let before_composition = composition.clone();
        let matte = image_routing::LayerMatte {
            enabled: true,
            input: image_routing::ImageInput::GroupOutput { group_id: removed },
            ..image_routing::LayerMatte::default()
        };
        let before_matte = matte;

        let mut staged_composition = composition.clone();
        staged_composition.remove_group_ungroup(removed).unwrap();
        let staged_mattes = stage_layer_mattes_after_group_removal([(layer_id, matte)], removed);

        assert_eq!(composition, before_composition);
        assert_eq!(matte, before_matte);
        assert!(matches!(
            staged_mattes[0].1.input,
            image_routing::ImageInput::MissingGroupOutput { group_id } if group_id == removed
        ));
        assert!(!staged_composition.contains_group(removed));
        staged_composition
            .insert_empty_group(composition::GroupName::new("Replacement").unwrap(), 0)
            .unwrap();
        assert!(matches!(
            staged_mattes[0].1.input,
            image_routing::ImageInput::MissingGroupOutput { group_id } if group_id == removed
        ));
    }

    #[test]
    fn stable_layer_bus_edit_survives_unrelated_reorder_without_revision_identity() {
        let top = stable_layer(11);
        let middle = stable_layer(22);
        let bottom = stable_layer(33);
        let mut reordered = legacy_runtime_composition(&[top, middle, bottom]).unwrap();
        reordered
            .move_root_item(composition::RuntimeRootItemKey::Layer(top), 0)
            .unwrap();
        let before = reordered.clone();

        let updated =
            stage_set_composition_layer_bus(&reordered, middle, composition::BusAssignment::B)
                .unwrap()
                .expect("stable direct layer still exists after unrelated reorder");

        assert_eq!(reordered, before);
        assert!(updated.root().iter().any(|item| matches!(
            item,
            composition::RuntimeRootItem::Layer { layer_id, bus: composition::BusAssignment::B }
                if *layer_id == middle
        )));
        assert!(stage_set_composition_layer_bus(
            &updated,
            stable_layer(999),
            composition::BusAssignment::A,
        )
        .unwrap()
        .is_none());
    }

    #[test]
    fn ordinary_move_rejects_group_split_without_mutating_the_tree() {
        let back = stable_layer(1);
        let grouped_back = stable_layer(2);
        let grouped_front = stable_layer(3);
        let group = runtime_group(7, &[grouped_back, grouped_front]);
        let composition = composition::RuntimeComposition::try_from_parts(
            vec![group],
            vec![
                composition::RuntimeRootItem::Group {
                    group_id: visual_rack::GroupId::new(7).unwrap(),
                },
                composition::RuntimeRootItem::Layer {
                    layer_id: back,
                    bus: composition::BusAssignment::Program,
                },
            ],
            Some(8),
            0.5,
        )
        .unwrap();
        let before = composition.clone();

        // Back-to-front would become [group member, direct layer, group
        // member], which cannot be represented without breaking the group.
        let error = stage_composition_reorder(&composition, &[grouped_front, back, grouped_back])
            .unwrap_err();
        assert!(error.contains("split group"));
        assert_eq!(composition, before);
    }

    #[test]
    fn removed_image_donor_becomes_explicitly_missing_and_never_retargets() {
        let consumer = stable_layer(10);
        let donor = stable_layer(42);
        let donor_position = performance::SavedLayerPosition::new(1).unwrap();
        let mut group = runtime_group(7, &[consumer]);
        let node_id = group
            .rack
            .push(visual_rack::RuntimeVisualNodeKind::Mask(
                visual_rack::RuntimeMaskParams::Image(visual_rack::RuntimeImageMatte {
                    tap: visual_rack::ResolvedImageTap {
                        source: visual_rack::ResolvedImageSource::SelectedLayer {
                            layer_id: donor,
                            saved_position: donor_position,
                            stage: image_routing::LayerImageStage::PostLocalEffects,
                        },
                        timing: visual_rack::EdgeTiming::CurrentFrame,
                    },
                    channel: visual_rack::MatteChannel::Luma,
                    invert: false,
                    amount: 1.0,
                    threshold: 0.5,
                    softness: 0.1,
                }),
            ))
            .unwrap();
        let group_id = group.id;
        let composition = composition::RuntimeComposition::try_from_parts(
            vec![group],
            vec![
                composition::RuntimeRootItem::Layer {
                    layer_id: donor,
                    bus: composition::BusAssignment::Program,
                },
                composition::RuntimeRootItem::Group { group_id },
            ],
            Some(8),
            0.5,
        )
        .unwrap();
        let removed = stage_composition_remove(&composition, &[consumer, donor], donor).unwrap();
        assert!(matches!(
            removed
                .group(group_id)
                .unwrap()
                .rack
                .image_mask_route(node_id)
                .unwrap()
                .source,
            visual_rack::ResolvedImageSource::MissingSelectedLayer {
                saved_position,
                stage: image_routing::LayerImageStage::PostLocalEffects,
            } if saved_position == donor_position
        ));
        assert_eq!(
            runtime_composition_front_to_back(&removed).unwrap(),
            [consumer]
        );
    }

    #[test]
    fn motion_donor_reorder_refreshes_provenance_and_removal_never_retargets() {
        let donor = stable_layer(42);
        let replacement = stable_layer(99);
        let zero = performance::SavedLayerPosition::new(0).unwrap();
        let one = performance::SavedLayerPosition::new(1).unwrap();
        let mut params = motion::MotionParams::default();
        params.transplant.donor = motion::MotionDonor::Selected {
            layer_id: donor,
            saved_position: zero,
        };

        refresh_motion_donor_saved_position(&mut params, &[(replacement, zero), (donor, one)]);
        assert_eq!(
            params.transplant.donor,
            motion::MotionDonor::Selected {
                layer_id: donor,
                saved_position: one,
            }
        );

        preserve_motion_donor_after_remove(&mut params, donor, one);
        assert_eq!(
            params.transplant.donor,
            motion::MotionDonor::Missing {
                saved_position: one
            }
        );

        // Filling the vacated persisted position with a different live layer
        // cannot revive or redirect the explicit tombstone.
        refresh_motion_donor_saved_position(&mut params, &[(replacement, one)]);
        assert_eq!(
            params.transplant.donor,
            motion::MotionDonor::Missing {
                saved_position: one
            }
        );
    }

    #[test]
    fn refresh_garden_route_actions_are_revisioned_historic_and_broad_reset_closed() {
        use web::state::WebAction;

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        let saved_position = performance::SavedLayerPosition::new(2).unwrap();
        app.temporal_params.originals.garden.gate = temporal::RefreshGardenGate::Matte;
        app.temporal_params.originals.garden.matte_route =
            temporal::RefreshGardenMatteRoute::MissingSelectedLayer {
                saved_position,
                stage: image_routing::LayerImageStage::PreLocalEffects,
            };
        let revision = app.layer_stack_revision;

        app.handle_web_action(WebAction::SetRefreshGardenMatteRoute {
            layer_id: None,
            stage: image_routing::LayerImageStage::PostLocalEffects,
            layer_stack_revision: revision,
        });
        assert_eq!(
            app.temporal_params.originals.garden.matte_route,
            temporal::RefreshGardenMatteRoute::None
        );
        app.handle_web_action(WebAction::UndoManual);
        assert_eq!(
            app.temporal_params.originals.garden.matte_route,
            temporal::RefreshGardenMatteRoute::MissingSelectedLayer {
                saved_position,
                stage: image_routing::LayerImageStage::PreLocalEffects,
            }
        );
        app.handle_web_action(WebAction::RedoManual);
        assert_eq!(
            app.temporal_params.originals.garden.matte_route,
            temporal::RefreshGardenMatteRoute::None
        );

        app.temporal_params.originals.garden.motion_route =
            temporal::RefreshGardenMotionRoute::MissingSelectedLayer { saved_position };
        app.handle_web_action(WebAction::SetRefreshGardenMotionRoute {
            layer_id: None,
            layer_stack_revision: revision.wrapping_add(1),
        });
        assert_eq!(
            app.temporal_params.originals.garden.motion_route,
            temporal::RefreshGardenMotionRoute::MissingSelectedLayer { saved_position }
        );
        assert!(app.composition_status.contains("stale"));

        let removed = stable_layer(91);
        app.temporal_params.originals.garden.matte_route =
            temporal::RefreshGardenMatteRoute::SelectedLayer {
                layer_id: removed,
                saved_position,
                stage: image_routing::LayerImageStage::PostLocalEffects,
            };
        app.temporal_params.originals.garden.motion_route =
            temporal::RefreshGardenMotionRoute::SelectedLayer {
                layer_id: removed,
                saved_position,
            };
        app.preserve_refresh_garden_routes_before_remove(1, removed);
        assert_eq!(
            app.temporal_params.originals.garden.matte_route,
            temporal::RefreshGardenMatteRoute::MissingSelectedLayer {
                saved_position: performance::SavedLayerPosition::new(1).unwrap(),
                stage: image_routing::LayerImageStage::PostLocalEffects,
            }
        );
        assert_eq!(
            app.temporal_params.originals.garden.motion_route,
            temporal::RefreshGardenMotionRoute::MissingSelectedLayer {
                saved_position: performance::SavedLayerPosition::new(1).unwrap(),
            }
        );
        app.refresh_refresh_garden_route_saved_positions();
        assert!(matches!(
            app.temporal_params.originals.garden.motion_route,
            temporal::RefreshGardenMotionRoute::MissingSelectedLayer { .. }
        ));

        app.handle_web_action(WebAction::SetTemporal {
            param: "garden_gate".into(),
            value: serde_json::json!("motion"),
        });
        assert_eq!(
            app.temporal_params.originals.garden.gate,
            temporal::RefreshGardenGate::Motion
        );
        app.handle_web_action(WebAction::ResetVisualProgram);
        assert_eq!(
            app.temporal_params.originals.garden,
            temporal::RefreshGardenParams::default()
        );
    }

    #[test]
    fn stale_creative_topology_edit_is_atomic_and_publishes_authoritative_status() {
        use web::state::{CreativeScopeSnapshot, WebAction};

        let web_state = WebState::new().expect("test token");
        let _web_snapshot_receiver = web_state.tx.subscribe();
        let mut app = App::new(None, None, web_state.clone());
        app.quantized_actions
            .push(WebAction::SetProgramFrozen { frozen: true });
        let before_master = app.master_rack.clone();
        let before_composition = app.composition.clone();
        let before_stack_revision = app.layer_stack_revision;
        let before_composition_revision = app.composition_revision;

        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 0,
            node_kind: "shift".into(),
            composition_revision: app.composition_revision.wrapping_add(1).max(1),
        });

        assert_eq!(app.master_rack, before_master);
        assert_eq!(app.composition, before_composition);
        assert_eq!(app.layer_stack_revision, before_stack_revision);
        assert_eq!(app.composition_revision, before_composition_revision);
        assert_eq!(app.quantized_actions.len(), 1);
        assert!(matches!(
            app.quantized_actions[0],
            WebAction::SetProgramFrozen { frozen: true }
        ));
        assert!(app
            .composition_status
            .contains("stale composition revision"));

        app.push_web_state();
        let published = web_state.app.try_read().expect("published app snapshot");
        assert_eq!(published.composition_revision, before_composition_revision);
        assert_eq!(published.creative.status, app.composition_status);
        assert_eq!(
            published.creative.master_rack.nodes.len(),
            before_master.len()
        );
    }

    #[test]
    fn creative_commit_impact_resets_only_real_topology_or_stack_changes() {
        assert_eq!(
            creative_commit_impact(false, false, false),
            CreativeCommitImpact::NoChange
        );
        assert_eq!(
            creative_commit_impact(false, true, true),
            CreativeCommitImpact::NoChange,
            "a duplicate topology command is not a generation boundary"
        );
        assert_eq!(
            creative_commit_impact(true, false, false),
            CreativeCommitImpact::ValuesOnly
        );
        assert_eq!(
            creative_commit_impact(true, true, false),
            CreativeCommitImpact::TopologyOrStack
        );
        assert_eq!(
            creative_commit_impact(true, false, true),
            CreativeCommitImpact::TopologyOrStack
        );
    }

    #[test]
    fn accepted_morph_transactions_choose_exactly_one_retained_pixel_reset() {
        assert_eq!(
            morph_partition_reset(false, false),
            MorphPartitionReset::None
        );
        assert_eq!(
            morph_partition_reset(true, false),
            MorphPartitionReset::BypassPartition
        );
        assert_eq!(
            morph_partition_reset(false, true),
            MorphPartitionReset::SourceCut
        );
        assert_eq!(
            morph_partition_reset(true, true),
            MorphPartitionReset::SourceCut,
            "the hard SourceCut owns the partition reset instead of doubling it"
        );

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        let initial_epoch = app.visual_epoch;
        app.finish_accepted_morph_partition_transaction(false, false);
        assert_eq!(app.visual_epoch, initial_epoch, "no change has no reset");

        app.finish_accepted_morph_partition_transaction(true, false);
        assert_eq!(
            app.visual_epoch,
            initial_epoch.wrapping_add(1),
            "a materialized partition change resets exactly once"
        );

        let before_hard_barrier = app.visual_epoch;
        app.finish_accepted_morph_partition_transaction(true, true);
        assert_eq!(
            app.visual_epoch,
            before_hard_barrier.wrapping_add(1),
            "SourceCut plus a partition change still resets exactly once"
        );
    }

    #[test]
    fn displace_browser_protocol_edits_values_and_barriers_its_route_by_revision() {
        use web::state::{
            CreativeImageSourceSnapshot, CreativeImageTapSnapshot, CreativeScopeSnapshot, WebAction,
        };

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.master_rack = RuntimeVisualRack::empty();

        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 0,
            node_kind: "displace".into(),
            composition_revision: app.composition_revision,
        });
        let node_id = app.master_rack.iter().next().unwrap().stable_id;
        let params = |app: &App| match app.master_rack.get(node_id).unwrap().kind {
            visual_rack::RuntimeVisualNodeKind::Displace(params) => params,
            _ => panic!("inserted node must be a displace"),
        };
        // A newly inserted node is the deterministic exact-bypass default.
        assert!(params(&app).is_exact_bypass());
        assert_eq!(
            params(&app).tap.source,
            visual_rack::ResolvedImageSource::OneBelow
        );
        assert_eq!(
            params(&app).boundary,
            visual_rack::DisplaceBoundary::Transparent
        );

        // Gains and the boundary travel on the ordinary coalescible action.
        let revision = app.composition_revision;
        let set = |app: &mut App, param: &str, value: serde_json::Value| {
            app.handle_web_action(WebAction::SetVisualNodeParam {
                scope: CreativeScopeSnapshot::Master,
                node_id: node_id.get().to_string(),
                node_kind: "displace".into(),
                param: param.into(),
                value,
                composition_revision: revision,
            });
        };
        set(&mut app, "amount_x", serde_json::json!(0.5));
        set(&mut app, "amount_y", serde_json::json!(-0.25));
        set(&mut app, "boundary", serde_json::json!("wrap"));
        assert_eq!(params(&app).amount_x, 0.5);
        assert_eq!(params(&app).amount_y, -0.25);
        assert_eq!(params(&app).boundary, visual_rack::DisplaceBoundary::Wrap);
        assert!(!params(&app).is_exact_bypass());

        // Hostile values clamp instead of escaping the ±1 UV domain, and the
        // route is refused on the value path.
        set(&mut app, "amount_x", serde_json::json!(42.0));
        assert_eq!(params(&app).amount_x, 1.0);
        set(&mut app, "donor_tap", serde_json::json!("one_below"));
        assert_eq!(
            params(&app).tap.source,
            visual_rack::ResolvedImageSource::OneBelow,
            "the donor route must reject the coalescible value path"
        );

        // The dedicated ordered action reroutes without disturbing the values.
        let clean_program = CreativeImageTapSnapshot {
            input: CreativeImageSourceSnapshot::CleanProgram,
            timing: visual_rack::EdgeTiming::PreviousFrame,
        };
        let route_revision = app.composition_revision;
        app.handle_web_action(WebAction::SetVisualNodeDisplaceRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            route: clean_program.clone(),
            composition_revision: route_revision,
        });
        assert_eq!(
            params(&app).tap.source,
            visual_rack::ResolvedImageSource::CleanProgram
        );
        assert_eq!(
            params(&app).tap.timing,
            visual_rack::EdgeTiming::PreviousFrame
        );
        assert_eq!(params(&app).amount_x, 1.0, "a reroute preserves the gains");
        assert_eq!(params(&app).amount_y, -0.25);
        assert_eq!(params(&app).boundary, visual_rack::DisplaceBoundary::Wrap);
        assert_ne!(
            app.composition_revision, route_revision,
            "a route change is a topology barrier and advances the revision"
        );

        // A stale revision is rejected outright; the live route is untouched.
        app.handle_web_action(WebAction::SetVisualNodeDisplaceRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            route: CreativeImageTapSnapshot {
                input: CreativeImageSourceSnapshot::OneBelow,
                timing: visual_rack::EdgeTiming::CurrentFrame,
            },
            composition_revision: route_revision,
        });
        assert_eq!(
            params(&app).tap.source,
            visual_rack::ResolvedImageSource::CleanProgram,
            "a stale revision must never apply a reroute"
        );

        // The route action is an ordered barrier and is never coalesced.
        let route_action = WebAction::SetVisualNodeDisplaceRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            route: clean_program,
            composition_revision: app.composition_revision,
        };
        assert!(App::quantized_action_key(&route_action).is_none());
        assert!(App::action_targets_master_rack(&route_action));

        // Addressing a node of another kind is a typed refusal, not a silent
        // rewrite of that node.
        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 1,
            node_kind: "grain".into(),
            composition_revision: app.composition_revision,
        });
        let grain_id = app.master_rack.iter().nth(1).unwrap().stable_id;
        app.handle_web_action(WebAction::SetVisualNodeDisplaceRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: grain_id.get().to_string(),
            route: CreativeImageTapSnapshot {
                input: CreativeImageSourceSnapshot::OneBelow,
                timing: visual_rack::EdgeTiming::CurrentFrame,
            },
            composition_revision: app.composition_revision,
        });
        assert!(matches!(
            app.master_rack.get(grain_id).unwrap().kind,
            visual_rack::RuntimeVisualNodeKind::Grain(_)
        ));

        // The etched gesture field is a member of the same closed route
        // vocabulary, so the same ordered action selects it — at the current
        // frame, from the master scope that owns the canvas, which would be a
        // self-cycle for any producer that lived in the composition graph.
        let canvas_revision = app.composition_revision;
        app.handle_web_action(WebAction::SetVisualNodeDisplaceRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            route: CreativeImageTapSnapshot {
                input: CreativeImageSourceSnapshot::GestureCanvas,
                timing: visual_rack::EdgeTiming::CurrentFrame,
            },
            composition_revision: canvas_revision,
        });
        assert_eq!(
            params(&app).tap.source,
            visual_rack::ResolvedImageSource::GestureCanvas
        );
        assert_eq!(
            params(&app).tap.timing,
            visual_rack::EdgeTiming::CurrentFrame
        );
        assert_eq!(params(&app).amount_x, 1.0, "a reroute preserves the gains");
        assert_ne!(app.composition_revision, canvas_revision);
    }

    #[test]
    fn residual_browser_protocol_edits_values_and_barriers_each_route_slot_by_revision() {
        use web::state::{
            CreativeImageSourceSnapshot, CreativeImageTapSnapshot, CreativeScopeSnapshot,
            ResidualRouteSlotSnapshot, WebAction,
        };

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.master_rack = RuntimeVisualRack::empty();

        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 0,
            node_kind: "residual".into(),
            composition_revision: app.composition_revision,
        });
        let node_id = app.master_rack.iter().next().unwrap().stable_id;
        let params = |app: &App| match app.master_rack.get(node_id).unwrap().kind {
            visual_rack::RuntimeVisualNodeKind::Residual(params) => params,
            _ => panic!("inserted node must be a residual"),
        };
        // A newly inserted node is the deterministic exact-bypass default with
        // both slots on the same neutral donor.
        assert!(params(&app).is_exact_bypass());
        assert_eq!(
            params(&app).structure.source,
            visual_rack::ResolvedImageSource::OneBelow
        );
        assert_eq!(
            params(&app).detail.source,
            visual_rack::ResolvedImageSource::OneBelow
        );
        assert_eq!(params(&app).block, visual_rack::ResidualBlock::Eight);
        assert_eq!(
            params(&app).quantization,
            visual_rack::ResidualQuantization::Off
        );
        assert_eq!(params(&app).detail_gain, 1.0);

        // Values, both discrete laws and the seed travel on the ordinary
        // coalescible action.
        let revision = app.composition_revision;
        let set = |app: &mut App, param: &str, value: serde_json::Value| {
            app.handle_web_action(WebAction::SetVisualNodeParam {
                scope: CreativeScopeSnapshot::Master,
                node_id: node_id.get().to_string(),
                node_kind: "residual".into(),
                param: param.into(),
                value,
                composition_revision: revision,
            });
        };
        set(&mut app, "mix", serde_json::json!(0.5));
        set(&mut app, "detail_gain", serde_json::json!(2.5));
        set(&mut app, "block", serde_json::json!("thirty_two"));
        set(&mut app, "quantization", serde_json::json!("coarse"));
        set(&mut app, "seed", serde_json::json!(0x00c0_ffee_u32));
        assert_eq!(params(&app).mix, 0.5);
        assert_eq!(params(&app).detail_gain, 2.5);
        assert_eq!(params(&app).block, visual_rack::ResidualBlock::ThirtyTwo);
        assert_eq!(
            params(&app).quantization,
            visual_rack::ResidualQuantization::Coarse
        );
        assert_eq!(params(&app).seed, 0x00c0_ffee);
        assert!(!params(&app).is_exact_bypass());

        // Hostile finite overshoot clamps and a non-finite value collapses to
        // the neutral fallback, never to a clamped extreme.
        set(&mut app, "mix", serde_json::json!(42.0));
        assert_eq!(params(&app).mix, 1.0);
        set(&mut app, "detail_gain", serde_json::json!(-9.0));
        assert_eq!(params(&app).detail_gain, 0.0);
        set(&mut app, "detail_gain", serde_json::json!(2.5));

        // Neither route may be rewritten on the coalescible value path.
        for param in ["structure_tap", "detail_tap"] {
            set(&mut app, param, serde_json::json!("one_below"));
        }
        assert_eq!(
            params(&app).structure.source,
            visual_rack::ResolvedImageSource::OneBelow,
            "the structure route must reject the coalescible value path"
        );
        assert_eq!(
            params(&app).detail.source,
            visual_rack::ResolvedImageSource::OneBelow,
            "the detail route must reject the coalescible value path"
        );

        // Each slot reroutes independently and leaves its partner alone.
        let clean_program = CreativeImageTapSnapshot {
            input: CreativeImageSourceSnapshot::CleanProgram,
            timing: visual_rack::EdgeTiming::PreviousFrame,
        };
        let structure_revision = app.composition_revision;
        app.handle_web_action(WebAction::SetVisualNodeResidualRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            slot: ResidualRouteSlotSnapshot::Structure,
            route: clean_program.clone(),
            composition_revision: structure_revision,
        });
        assert_eq!(
            params(&app).structure.source,
            visual_rack::ResolvedImageSource::CleanProgram
        );
        assert_eq!(
            params(&app).structure.timing,
            visual_rack::EdgeTiming::PreviousFrame
        );
        assert_eq!(
            params(&app).detail.source,
            visual_rack::ResolvedImageSource::OneBelow,
            "rerouting one slot must never move its partner"
        );
        assert_ne!(
            app.composition_revision, structure_revision,
            "a route change is a topology barrier and advances the revision"
        );
        assert_eq!(params(&app).mix, 1.0, "a reroute preserves the values");
        assert_eq!(params(&app).detail_gain, 2.5);
        assert_eq!(params(&app).block, visual_rack::ResidualBlock::ThirtyTwo);
        assert_eq!(
            params(&app).quantization,
            visual_rack::ResidualQuantization::Coarse
        );
        assert_eq!(params(&app).seed, 0x00c0_ffee);

        let detail_revision = app.composition_revision;
        app.handle_web_action(WebAction::SetVisualNodeResidualRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            slot: ResidualRouteSlotSnapshot::Detail,
            route: CreativeImageTapSnapshot {
                input: CreativeImageSourceSnapshot::AllBelow,
                timing: visual_rack::EdgeTiming::CurrentFrame,
            },
            composition_revision: detail_revision,
        });
        assert_eq!(
            params(&app).detail.source,
            visual_rack::ResolvedImageSource::AllBelow
        );
        assert_eq!(
            params(&app).structure.source,
            visual_rack::ResolvedImageSource::CleanProgram,
            "the structure route survives a detail reroute"
        );

        // A stale revision is rejected outright on either slot; both live
        // routes are untouched.
        for slot in [
            ResidualRouteSlotSnapshot::Structure,
            ResidualRouteSlotSnapshot::Detail,
        ] {
            app.handle_web_action(WebAction::SetVisualNodeResidualRoute {
                scope: CreativeScopeSnapshot::Master,
                node_id: node_id.get().to_string(),
                slot,
                route: CreativeImageTapSnapshot {
                    input: CreativeImageSourceSnapshot::OneBelow,
                    timing: visual_rack::EdgeTiming::CurrentFrame,
                },
                composition_revision: detail_revision,
            });
        }
        assert_eq!(
            params(&app).structure.source,
            visual_rack::ResolvedImageSource::CleanProgram,
            "a stale revision must never apply a reroute"
        );
        assert_eq!(
            params(&app).detail.source,
            visual_rack::ResolvedImageSource::AllBelow
        );

        // The route action is an ordered barrier that is never beat-latched
        // and is always recognized as master-rack work.
        let route_action = WebAction::SetVisualNodeResidualRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            slot: ResidualRouteSlotSnapshot::Structure,
            route: clean_program,
            composition_revision: app.composition_revision,
        };
        assert!(App::quantized_action_key(&route_action).is_none());
        assert!(App::action_targets_master_rack(&route_action));

        // Addressing a node of another kind is a typed refusal on either slot,
        // not a silent rewrite of that node.
        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 1,
            node_kind: "grain".into(),
            composition_revision: app.composition_revision,
        });
        let grain_id = app.master_rack.iter().nth(1).unwrap().stable_id;
        for slot in [
            ResidualRouteSlotSnapshot::Structure,
            ResidualRouteSlotSnapshot::Detail,
        ] {
            app.handle_web_action(WebAction::SetVisualNodeResidualRoute {
                scope: CreativeScopeSnapshot::Master,
                node_id: grain_id.get().to_string(),
                slot,
                route: CreativeImageTapSnapshot {
                    input: CreativeImageSourceSnapshot::OneBelow,
                    timing: visual_rack::EdgeTiming::CurrentFrame,
                },
                composition_revision: app.composition_revision,
            });
        }
        assert!(matches!(
            app.master_rack.get(grain_id).unwrap().kind,
            visual_rack::RuntimeVisualNodeKind::Grain(_)
        ));

        // The published snapshot carries both routes and both diagnostics.
        let _web_snapshot_receiver = app.web_state.tx.subscribe();
        app.push_web_state();
        let published = app.web_state.app.try_read().expect("published snapshot");
        let node = published
            .creative
            .master_rack
            .nodes
            .iter()
            .find(|node| node.node_id == node_id.get().to_string())
            .expect("the residual node is published");
        assert_eq!(node.kind, "residual");
        assert_eq!(
            node.params["structure_tap"]["input"]["source"],
            "clean_program"
        );
        assert_eq!(node.params["detail_tap"]["input"]["source"], "all_below");
        assert_eq!(node.params["block"], "thirty_two");
        assert_eq!(node.params["quantization"], "coarse");
        assert_eq!(node.params["seed"], 0x00c0_ffee_u32);
        assert_eq!(node.params["diagnostic"], "");
    }

    /// `ResetVisualProgram` replaces the master rack wholesale with the
    /// synthetic legacy rack, so every reduced-resolution block-mean surface a
    /// Residual node owned must be released with it. Nothing may survive the
    /// swap, including a route edit already latched for a later downbeat.
    #[test]
    fn resetting_the_master_visual_program_releases_every_residual_mean_surface() {
        use web::state::{
            CreativeImageSourceSnapshot, CreativeImageTapSnapshot, CreativeScopeSnapshot,
            ResidualRouteSlotSnapshot, WebAction,
        };

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.master_rack = RuntimeVisualRack::empty();
        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 0,
            node_kind: "residual".into(),
            composition_revision: app.composition_revision,
        });
        let node_id = app.master_rack.iter().next().unwrap().stable_id;
        app.handle_web_action(WebAction::SetVisualNodeParam {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            node_kind: "residual".into(),
            param: "mix".into(),
            value: serde_json::json!(1.0),
            composition_revision: app.composition_revision,
        });

        // A live Residual owns exactly two reduced-resolution surfaces and two
        // reduced passes, on top of its single full-frame pass.
        let live = app.master_rack.resource_budget().expect("live rack budget");
        assert_eq!(live.reduced_resolution_surfaces, 2);
        assert_eq!(live.reduced_resolution_passes, 2);
        let live_signature = app.master_rack.topology_signature();

        // Latch a route edit for a later downbeat and freeze the program, so
        // the reset has to purge queued work as well as live topology.
        app.quantized_actions
            .push(WebAction::SetVisualNodeResidualRoute {
                scope: CreativeScopeSnapshot::Master,
                node_id: node_id.get().to_string(),
                slot: ResidualRouteSlotSnapshot::Detail,
                route: CreativeImageTapSnapshot {
                    input: CreativeImageSourceSnapshot::AllBelow,
                    timing: visual_rack::EdgeTiming::CurrentFrame,
                },
                composition_revision: app.composition_revision,
            });
        app.quantized_actions.push(WebAction::SetLayerPaused {
            index: 0,
            layer_id: None,
            paused: true,
        });

        app.handle_web_action(WebAction::ResetVisualProgram);

        // No Residual node survives, so the reset rack declares no reduced
        // pass and no reduced surface at all.
        assert!(
            !app.master_rack
                .iter()
                .any(|node| node.kind.tag() == visual_rack::NodeKindTag::Residual),
            "the reset master rack must hold no residual node"
        );
        let reset = app
            .master_rack
            .resource_budget()
            .expect("reset rack budget");
        assert_eq!(reset.reduced_resolution_surfaces, 0);
        assert_eq!(reset.reduced_resolution_passes, 0);
        assert_ne!(
            app.master_rack.topology_signature(),
            live_signature,
            "the executor must not be able to reuse a prepared segment whose \
             mean surfaces belong to the discarded rack"
        );

        // The latched reroute is purged; unrelated latched transport survives.
        assert!(
            !app.quantized_actions
                .iter()
                .any(App::action_targets_master_rack),
            "a latched master route edit must never resurrect a reset node"
        );
        assert!(app
            .quantized_actions
            .iter()
            .any(|action| matches!(action, WebAction::SetLayerPaused { .. })));
    }

    /// Closes the four main.rs sites for the Symmetry route action: the
    /// creative admission `matches!`, the dispatch arm, `action_targets_master_
    /// rack`, and the legacy-dispatch list. Omitting the admission guard
    /// silently falls through to the legacy `unreachable!`, and omitting the
    /// master-rack predicate lets a latched reroute survive a visual reset.
    #[test]
    fn symmetry_browser_protocol_edits_values_and_barriers_each_slot_by_revision() {
        use web::state::{
            CreativeImageSourceSnapshot, CreativeImageTapSnapshot, CreativeScopeSnapshot,
            SymmetryRouteSnapshot, WebAction,
        };

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.master_rack = RuntimeVisualRack::empty();

        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 0,
            node_kind: "symmetry".into(),
            composition_revision: app.composition_revision,
        });
        let node_id = app
            .master_rack
            .iter()
            .next()
            .expect("the browser can insert a Symmetry Field")
            .stable_id;
        let params = |app: &App| match app.master_rack.get(node_id).unwrap().kind {
            visual_rack::RuntimeVisualNodeKind::Symmetry(params) => params,
            _ => panic!("inserted node must be a symmetry field"),
        };
        // A newly inserted node is the deterministic exact-bypass default.
        assert!(params(&app).is_exact_bypass());
        assert_eq!(params(&app).mode, symmetry::SymmetryMode::Cyclic);
        assert_eq!(
            params(&app).boundary,
            symmetry::SymmetryBoundary::Transparent
        );
        assert!(params(&app).source_mask.is_carrier_only());

        // Geometry, masks, discrete laws, and the seed all travel on the one
        // coalescible value action.
        let revision = app.composition_revision;
        let set = |app: &mut App, param: &str, value: serde_json::Value| {
            app.handle_web_action(WebAction::SetVisualNodeParam {
                scope: CreativeScopeSnapshot::Master,
                node_id: node_id.get().to_string(),
                node_kind: "symmetry".into(),
                param: param.into(),
                value,
                composition_revision: revision,
            });
        };
        set(&mut app, "symmetry_base_folds", serde_json::json!(6.0));
        set(&mut app, "symmetry_mode", serde_json::json!("planar_pmm"));
        set(
            &mut app,
            "symmetry_boundary",
            serde_json::json!("cellular_reentry"),
        );
        set(&mut app, "symmetry_hue_span", serde_json::json!(0.5));
        set(&mut app, "symmetry_seed", serde_json::json!(4_242));
        set(&mut app, "symmetry_source_donor1", serde_json::json!(true));
        set(&mut app, "symmetry_motion_slot0", serde_json::json!(true));
        assert_eq!(params(&app).base_folds, 6.0);
        assert_eq!(params(&app).mode, symmetry::SymmetryMode::PlanarPmm);
        assert_eq!(
            params(&app).boundary,
            symmetry::SymmetryBoundary::CellularReentry
        );
        assert_eq!(params(&app).hue_span, 0.5);
        assert_eq!(params(&app).seed, 4_242);
        assert!(params(&app).source_mask.donor1);
        assert!(params(&app).motion_mask.slot0);
        assert!(!params(&app).is_exact_bypass());

        // Hostile values clamp into the declared range, and every route key is
        // refused on the value path.
        set(&mut app, "symmetry_base_folds", serde_json::json!(9_000.0));
        assert_eq!(params(&app).base_folds, 32.0);
        set(&mut app, "symmetry_hue_span", serde_json::json!(f64::NAN));
        assert_eq!(params(&app).hue_span, 0.5, "a non-finite edit is refused");
        for key in [
            "symmetry_donor0_tap",
            "symmetry_donor1_tap",
            "symmetry_motion0_donor",
            "symmetry_motion1_donor",
        ] {
            set(&mut app, key, serde_json::json!("one_below"));
        }
        let default_tap = visual_rack::ResolvedImageTap {
            source: visual_rack::ResolvedImageSource::OneBelow,
            timing: visual_rack::EdgeTiming::CurrentFrame,
        };
        assert_eq!(
            params(&app).donors,
            [default_tap; symmetry::SYMMETRY_IMAGE_SLOTS],
            "the four routes must reject the coalescible value path"
        );

        // The dedicated ordered action reroutes exactly one slot and leaves the
        // other three plus every value untouched.
        let clean_program = CreativeImageTapSnapshot {
            input: CreativeImageSourceSnapshot::CleanProgram,
            timing: visual_rack::EdgeTiming::PreviousFrame,
        };
        let route_revision = app.composition_revision;
        app.handle_web_action(WebAction::SetVisualNodeSymmetryRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            route: SymmetryRouteSnapshot::Image {
                index: 1,
                route: clean_program.clone(),
            },
            composition_revision: route_revision,
        });
        assert_eq!(
            params(&app).donors[1].source,
            visual_rack::ResolvedImageSource::CleanProgram
        );
        assert_eq!(
            params(&app).donors[0],
            default_tap,
            "slot index is route identity: slot 1 never writes slot 0"
        );
        assert_eq!(params(&app).base_folds, 32.0, "a reroute preserves values");
        assert_eq!(params(&app).seed, 4_242);
        assert_ne!(
            app.composition_revision, route_revision,
            "a route change is a topology barrier and advances the revision"
        );

        // A stale revision is rejected outright; the live route is untouched.
        app.handle_web_action(WebAction::SetVisualNodeSymmetryRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            route: SymmetryRouteSnapshot::Image {
                index: 1,
                route: CreativeImageTapSnapshot {
                    input: CreativeImageSourceSnapshot::OneBelow,
                    timing: visual_rack::EdgeTiming::CurrentFrame,
                },
            },
            composition_revision: route_revision,
        });
        assert_eq!(
            params(&app).donors[1].source,
            visual_rack::ResolvedImageSource::CleanProgram,
            "a stale revision must never apply a reroute"
        );

        // An out-of-range slot is a typed refusal, never a fallback onto slot 0.
        app.handle_web_action(WebAction::SetVisualNodeSymmetryRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            route: SymmetryRouteSnapshot::Image {
                index: 7,
                route: clean_program.clone(),
            },
            composition_revision: app.composition_revision,
        });
        assert_eq!(params(&app).donors[0], default_tap);
        assert!(app.composition_status.contains("slot 7 does not exist"));

        // A motion slot clears with an absent layer.
        app.handle_web_action(WebAction::SetVisualNodeSymmetryRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            route: SymmetryRouteSnapshot::Motion {
                index: 1,
                layer_id: None,
            },
            composition_revision: app.composition_revision,
        });
        assert_eq!(params(&app).motion[1], motion::MotionDonor::None);

        // The route action is an ordered barrier, is never latched, and is
        // recognized as master-rack work so a visual reset purges it.
        let route_action = WebAction::SetVisualNodeSymmetryRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            route: SymmetryRouteSnapshot::Image {
                index: 0,
                route: clean_program,
            },
            composition_revision: app.composition_revision,
        };
        assert!(App::quantized_action_key(&route_action).is_none());
        assert!(App::action_targets_master_rack(&route_action));

        // Addressing a node of another kind is a typed refusal.
        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 1,
            node_kind: "grain".into(),
            composition_revision: app.composition_revision,
        });
        let grain_id = app.master_rack.iter().nth(1).unwrap().stable_id;
        app.handle_web_action(WebAction::SetVisualNodeSymmetryRoute {
            scope: CreativeScopeSnapshot::Master,
            node_id: grain_id.get().to_string(),
            route: SymmetryRouteSnapshot::Motion {
                index: 0,
                layer_id: None,
            },
            composition_revision: app.composition_revision,
        });
        assert!(matches!(
            app.master_rack.get(grain_id).unwrap().kind,
            visual_rack::RuntimeVisualNodeKind::Grain(_)
        ));
        assert!(app.composition_status.contains("is not a symmetry field"));
    }

    #[test]
    fn creative_values_and_duplicates_preserve_history_but_topology_resets_once() {
        use web::state::{CreativeScopeSnapshot, RerollMode, RerollScope, WebAction};

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.master_rack = RuntimeVisualRack::empty();
        let initial_epoch = app.visual_epoch;
        let initial_revision = app.composition_revision;

        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 0,
            node_kind: "shift".into(),
            composition_revision: initial_revision,
        });
        let node_id = app.master_rack.iter().next().unwrap().stable_id;
        assert_eq!(app.visual_epoch, initial_epoch.wrapping_add(1));
        assert_eq!(
            app.composition_revision,
            initial_revision.wrapping_add(1).max(1)
        );

        app.master_rack.get_mut(node_id).unwrap().wet = 0.2;
        let empty_racks = app.layer_racks();
        let a = morph::MorphSlot::capture_with_composition(
            &app.master_effects,
            &app.master_transform,
            &app.ntsc_params,
            &app.temporal_params,
            &app.layers,
            &app.master_rack,
            &empty_racks,
            &app.composition,
        )
        .unwrap();
        app.master_rack.get_mut(node_id).unwrap().wet = 0.8;
        let b = morph::MorphSlot::capture_with_composition(
            &app.master_effects,
            &app.master_transform,
            &app.ntsc_params,
            &app.temporal_params,
            &app.layers,
            &app.master_rack,
            &empty_racks,
            &app.composition,
        )
        .unwrap();
        app.master_rack.get_mut(node_id).unwrap().wet = 0.2;
        app.morph.a = Some(a);
        app.morph.b = Some(b);
        app.morph.t = 0.5;

        let warm_epoch = app.visual_epoch;
        let stable_revision = app.composition_revision;
        let set_wet = |value| WebAction::SetVisualNodeParam {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            node_kind: "shift".into(),
            param: "wet".into(),
            value: serde_json::json!(value),
            composition_revision: stable_revision,
        };
        app.handle_web_action(set_wet(0.6));
        assert!(!app.morph.active());
        assert!((app.master_rack.get(node_id).unwrap().wet - 0.6).abs() < 1.0e-6);
        assert_eq!(app.visual_epoch, warm_epoch);
        assert_eq!(app.composition_revision, stable_revision);

        app.handle_web_action(set_wet(0.6));
        assert_eq!(app.visual_epoch, warm_epoch);
        assert_eq!(app.composition_revision, stable_revision);

        app.handle_web_action(WebAction::SetCompositionBusCrossfade { value: 0.25 });
        assert_eq!(app.composition.bus_crossfade(), 0.25);
        assert_eq!(app.visual_epoch, warm_epoch);
        app.handle_web_action(WebAction::SetCompositionBusCrossfade { value: 0.25 });
        assert_eq!(app.visual_epoch, warm_epoch);

        let before_dice = app.master_rack.clone();
        app.handle_web_action(WebAction::Reroll {
            scope: RerollScope::Master,
            index: None,
            layer_id: None,
            group_id: None,
            stack_revision: None,
            seed: Some(73),
            mode: RerollMode::Variation,
            amount: 2.0,
            include_grain_controls: false,
            include_transform: false,
            include_rack_controls: true,
            include_group_controls: false,
            keep_source: false,
            keep_modulation: false,
            keep_output_chain: false,
        });
        assert_ne!(app.master_rack, before_dice);
        assert!(!app.master_motion.shutter.is_exact_zero());
        assert_eq!(app.visual_epoch, warm_epoch);
        assert_eq!(
            app.composition_revision,
            stable_revision.wrapping_add(1).max(1),
            "M4 Variation activates the previously zero shutter once without resetting visual history"
        );
        let post_dice_revision = app.composition_revision;

        app.handle_web_action(WebAction::MoveVisualNode {
            scope: CreativeScopeSnapshot::Master,
            node_id: node_id.get().to_string(),
            to: 0,
            composition_revision: post_dice_revision,
        });
        assert_eq!(app.visual_epoch, warm_epoch);
        assert_eq!(app.composition_revision, post_dice_revision);

        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 1,
            node_kind: "grain".into(),
            composition_revision: post_dice_revision,
        });
        assert_eq!(app.visual_epoch, warm_epoch.wrapping_add(1));
        assert_eq!(
            app.composition_revision,
            post_dice_revision.wrapping_add(1).max(1),
            "one actual topology edge is exactly one revision boundary"
        );
    }

    #[test]
    fn group_and_matte_values_preserve_history_around_real_route_edges() {
        use web::state::{
            CreativeImageSourceSnapshot, CreativeImageTapSnapshot, RerollMode, RerollScope,
            WebAction,
        };

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        let initial_epoch = app.visual_epoch;
        let initial_revision = app.composition_revision;
        app.handle_web_action(WebAction::CreateCompositionGroup {
            name: "History law".into(),
            member_layer_ids: Vec::new(),
            root_index: 0,
            composition_revision: initial_revision,
        });
        let group_id = app.composition.groups().next().unwrap().id;
        assert_eq!(app.visual_epoch, initial_epoch.wrapping_add(1));
        let group_epoch = app.visual_epoch;
        let group_revision = app.composition_revision;

        let set_opacity = |value| WebAction::SetCompositionGroupParam {
            group_id: group_id.get().to_string(),
            param: "opacity".into(),
            value: serde_json::json!(value),
            composition_revision: group_revision,
        };
        app.handle_web_action(set_opacity(0.4));
        app.handle_web_action(set_opacity(0.4));
        assert_eq!(app.composition.group(group_id).unwrap().opacity, 0.4);
        assert_eq!(app.visual_epoch, group_epoch);
        assert_eq!(app.composition_revision, group_revision);

        app.handle_web_action(WebAction::SetCompositionGroupMatteRoute {
            group_id: group_id.get().to_string(),
            route: Some(CreativeImageTapSnapshot {
                input: CreativeImageSourceSnapshot::OneBelow,
                timing: visual_rack::EdgeTiming::CurrentFrame,
            }),
            channel: "alpha".into(),
            invert: false,
            composition_revision: group_revision,
        });
        assert_eq!(app.visual_epoch, group_epoch.wrapping_add(1));
        assert_eq!(
            app.composition_revision,
            group_revision.wrapping_add(1).max(1)
        );
        let matte_epoch = app.visual_epoch;
        let matte_revision = app.composition_revision;

        let set_amount = |value| WebAction::SetCompositionGroupMatteParam {
            group_id: group_id.get().to_string(),
            param: "amount".into(),
            value: serde_json::json!(value),
            composition_revision: matte_revision,
        };
        app.handle_web_action(set_amount(0.35));
        app.handle_web_action(set_amount(0.35));
        assert_eq!(
            app.composition
                .group(group_id)
                .unwrap()
                .matte
                .unwrap()
                .amount,
            0.35
        );
        assert_eq!(app.visual_epoch, matte_epoch);
        assert_eq!(app.composition_revision, matte_revision);

        let before_dice = app.composition.group(group_id).unwrap().matte.unwrap();
        app.handle_web_action(WebAction::Reroll {
            scope: RerollScope::Group,
            index: None,
            layer_id: None,
            group_id: Some(group_id.get().to_string()),
            stack_revision: None,
            seed: Some(107),
            mode: RerollMode::Variation,
            amount: 2.0,
            include_grain_controls: false,
            include_transform: false,
            include_rack_controls: false,
            include_group_controls: true,
            keep_source: false,
            keep_modulation: false,
            keep_output_chain: false,
        });
        let after_dice = app.composition.group(group_id).unwrap().matte.unwrap();
        assert_ne!(after_dice, before_dice);
        assert_eq!(after_dice.tap, before_dice.tap);
        assert_eq!(after_dice.channel, before_dice.channel);
        assert_eq!(after_dice.invert, before_dice.invert);
        assert_eq!(app.visual_epoch, matte_epoch);
        assert_eq!(app.composition_revision, matte_revision);
    }

    #[test]
    fn successful_group_delete_tombstones_stable_modulation_only_after_commit() {
        use modulation::{
            GroupModParameter, SavedMissingTarget, SavedStableModTarget, StableModTarget,
        };
        use web::state::WebAction;

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.handle_web_action(WebAction::CreateCompositionGroup {
            name: "Mod owner".into(),
            member_layer_ids: Vec::new(),
            root_index: 0,
            composition_revision: app.composition_revision,
        });
        let group_id = app.composition.groups().next().unwrap().id;
        let target = StableModTarget::parse(&format!("group/{}/opacity", group_id.get())).unwrap();
        app.mod_matrix.routings.push(modulation::Routing::new(
            modulation::ModSource::Lfo(0),
            target.to_string(),
            0.75,
        ));
        let route_id = app.mod_matrix.routings[0].route_id();
        let revision = app.composition_revision;

        app.handle_web_action(WebAction::RemoveCompositionGroup {
            group_id: group_id.get().to_string(),
            composition_revision: revision.wrapping_add(1).max(1),
        });
        assert!(app.composition.contains_group(group_id));
        assert_eq!(app.mod_matrix.routings[0].stable_target(), Some(target));
        assert!(app.mod_matrix.routings[0].saved_missing_target().is_none());

        app.handle_web_action(WebAction::RemoveCompositionGroup {
            group_id: group_id.get().to_string(),
            composition_revision: revision,
        });
        assert!(!app.composition.contains_group(group_id));
        let routing = &app.mod_matrix.routings[0];
        assert_eq!(routing.route_id(), route_id);
        assert!(routing.stable_target().is_none());
        assert_eq!(
            routing.saved_missing_target(),
            Some(SavedStableModTarget::MissingGroup {
                group_id,
                missing_target: SavedMissingTarget::GroupValue {
                    parameter: GroupModParameter::Opacity,
                },
            })
        );
    }

    #[test]
    fn stable_scalar_edits_land_after_unrelated_topology_then_reorder_and_delete_by_id() {
        use web::state::{CreativeScopeSnapshot, WebAction};

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.master_rack = RuntimeVisualRack::empty();

        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 0,
            node_kind: "shift".into(),
            composition_revision: app.composition_revision,
        });
        let shift_id = app.master_rack.iter().next().unwrap().stable_id;
        let node_scalar_revision = app.composition_revision;

        app.handle_web_action(WebAction::CreateCompositionGroup {
            name: "Stable group".into(),
            member_layer_ids: Vec::new(),
            root_index: 0,
            composition_revision: app.composition_revision,
        });
        let group_id = app.composition.groups().next().unwrap().id;
        assert_ne!(app.composition_revision, node_scalar_revision);
        app.handle_web_action(WebAction::SetVisualNodeParam {
            scope: CreativeScopeSnapshot::Master,
            node_id: shift_id.get().to_string(),
            node_kind: "shift".into(),
            param: "wet".into(),
            value: serde_json::json!(0.37),
            composition_revision: node_scalar_revision,
        });
        assert!((app.master_rack.get(shift_id).unwrap().wet - 0.37).abs() < 1.0e-6);

        let group_scalar_revision = app.composition_revision;
        app.handle_web_action(WebAction::InsertVisualNode {
            scope: CreativeScopeSnapshot::Master,
            index: 1,
            node_kind: "grain".into(),
            composition_revision: app.composition_revision,
        });
        let grain_id = app
            .master_rack
            .iter()
            .find(|node| node.stable_id != shift_id)
            .unwrap()
            .stable_id;
        let after_insert_revision = app.composition_revision;
        app.handle_web_action(WebAction::SetCompositionGroupParam {
            group_id: group_id.get().to_string(),
            param: "opacity".into(),
            value: serde_json::json!(0.42),
            composition_revision: group_scalar_revision,
        });
        assert_eq!(app.composition_revision, after_insert_revision);
        assert!((app.composition.group(group_id).unwrap().opacity - 0.42).abs() < 1.0e-6);

        app.handle_web_action(WebAction::MoveVisualNode {
            scope: CreativeScopeSnapshot::Master,
            node_id: shift_id.get().to_string(),
            to: 1,
            composition_revision: app.composition_revision,
        });
        assert_eq!(
            app.master_rack
                .iter()
                .map(|node| node.stable_id)
                .collect::<Vec<_>>(),
            [grain_id, shift_id]
        );
        app.handle_web_action(WebAction::RemoveVisualNode {
            scope: CreativeScopeSnapshot::Master,
            node_id: grain_id.get().to_string(),
            composition_revision: app.composition_revision,
        });
        assert_eq!(
            app.master_rack
                .iter()
                .map(|node| node.stable_id)
                .collect::<Vec<_>>(),
            [shift_id]
        );
        assert!((app.master_rack.get(shift_id).unwrap().wet - 0.37).abs() < 1.0e-6);

        let revision_after_delete = app.composition_revision;
        app.handle_web_action(WebAction::SetVisualNodeParam {
            scope: CreativeScopeSnapshot::Master,
            node_id: grain_id.get().to_string(),
            node_kind: "grain".into(),
            param: "wet".into(),
            value: serde_json::json!(0.9),
            composition_revision: group_scalar_revision,
        });
        assert_eq!(app.composition_revision, revision_after_delete);
        assert!(app.master_rack.get(grain_id).is_none());
    }

    #[test]
    fn failed_current_frame_group_cycle_keeps_graph_revisions_and_queues_unchanged() {
        use web::state::{
            CreativeImageSourceSnapshot, CreativeImageTapSnapshot, CreativeScopeSnapshot, WebAction,
        };

        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.master_rack = RuntimeVisualRack::empty();
        let mut first = runtime_group(7, &[]);
        let second_id = visual_rack::GroupId::new(8).unwrap();
        push_image_mask(
            &mut first.rack,
            visual_rack::ResolvedImageSource::GroupOutput(second_id),
        );
        let mut second = runtime_group(8, &[]);
        let second_mask =
            push_image_mask(&mut second.rack, visual_rack::ResolvedImageSource::OneBelow);
        app.composition = composition::RuntimeComposition::try_from_parts(
            vec![first, second],
            vec![
                composition::RuntimeRootItem::Group {
                    group_id: visual_rack::GroupId::new(7).unwrap(),
                },
                composition::RuntimeRootItem::Group {
                    group_id: second_id,
                },
            ],
            Some(9),
            0.5,
        )
        .unwrap();
        app.quantized_actions
            .push(WebAction::SetBlackout { enabled: true });
        let before_master = app.master_rack.clone();
        let before_composition = app.composition.clone();
        let before_stack_revision = app.layer_stack_revision;
        let before_composition_revision = app.composition_revision;

        app.handle_web_action(WebAction::SetVisualNodeRoute {
            scope: CreativeScopeSnapshot::Group {
                group_id: second_id.get().to_string(),
            },
            node_id: second_mask.get().to_string(),
            route: CreativeImageTapSnapshot {
                input: CreativeImageSourceSnapshot::GroupOutput {
                    group_id: "7".into(),
                },
                timing: visual_rack::EdgeTiming::CurrentFrame,
            },
            channel: "alpha".into(),
            invert: false,
            composition_revision: app.composition_revision,
        });

        assert_eq!(app.master_rack, before_master);
        assert_eq!(app.composition, before_composition);
        assert_eq!(app.layer_stack_revision, before_stack_revision);
        assert_eq!(app.composition_revision, before_composition_revision);
        assert_eq!(app.quantized_actions.len(), 1);
        assert!(matches!(
            app.quantized_actions[0],
            WebAction::SetBlackout { enabled: true }
        ));
        assert!(
            app.composition_status
                .to_ascii_lowercase()
                .contains("cycle"),
            "unexpected status: {}",
            app.composition_status
        );
    }

