    #[test]
    fn selective_worker_gate_separates_busy_from_unavailable_metrics() {
        let mut metrics = ntsc::NtscPathMetrics::default();
        assert!(selective_ntsc_gpu_gate_is_open(
            ntsc::NtscSubmitOutcome::Accepted,
            &mut metrics,
        ));
        assert_eq!(metrics, ntsc::NtscPathMetrics::default());

        assert!(!selective_ntsc_gpu_gate_is_open(
            ntsc::NtscSubmitOutcome::Busy,
            &mut metrics,
        ));
        assert_eq!(metrics.attempted, 1);
        assert_eq!(metrics.skipped, 1);
        assert_eq!(metrics.unavailable, 0);

        assert!(!selective_ntsc_gpu_gate_is_open(
            ntsc::NtscSubmitOutcome::Unavailable,
            &mut metrics,
        ));
        assert_eq!(metrics.attempted, 2);
        assert_eq!(metrics.skipped, 1);
        assert_eq!(metrics.unavailable, 1);
    }

    #[test]
    fn paused_selective_edges_hold_disabled_and_legacy_in_both_directions() {
        for direct in [LiveNtscPath::Disabled, LiveNtscPath::LegacyGlobal] {
            assert!(is_selective_path_edge(
                direct,
                LiveNtscPath::SelectivePerLayer
            ));
            assert!(is_selective_path_edge(
                LiveNtscPath::SelectivePerLayer,
                direct
            ));

            // A paused edge retains slot2 through all subsequent paused
            // redraws, and cannot tag those held pixels as new direct/legacy
            // output for Spout or the global NTSC worker.
            assert!(!direct_path_may_replace_selective_hold(true, true));
            assert!(!raw_audience_readback_required(
                false, true, direct, true, false
            ));

            // Resume permits the first proper direct render. Only after that
            // logical hold release may the matching path schedule readback.
            assert!(direct_path_may_replace_selective_hold(false, true));
            assert!(raw_audience_readback_required(
                false, false, direct, true, false
            ));
            assert_eq!(
                raw_audience_readback_required(false, false, direct, false, false),
                direct == LiveNtscPath::LegacyGlobal
            );
            // B5: an armed mosh requires the readback on every path, even
            // with Spout off — but never through a hold and never under
            // blackout.
            assert!(raw_audience_readback_required(
                false, false, direct, false, true
            ));
            assert!(!raw_audience_readback_required(
                false, true, direct, false, true
            ));
            assert!(!raw_audience_readback_required(
                true, false, direct, false, true
            ));
        }
        assert!(raw_audience_readback_required(
            false,
            false,
            LiveNtscPath::SelectivePerLayer,
            false,
            true
        ));
        assert!(!is_selective_path_edge(
            LiveNtscPath::Disabled,
            LiveNtscPath::LegacyGlobal
        ));
    }

    #[test]
    fn linked_temporal_dry_invalidates_delayed_mosh_work_before_reentry() {
        let visual_epoch = 41_u64;
        let mut generation = 1_u64;
        let mut was_active = false;
        let mut retained = None;

        update_mosh_interval(true, &mut was_active, &mut generation, &mut retained);
        let pre_dry_generation = generation;
        retained = Some((visual_epoch, generation, vec![1_u8, 2, 3, 4]));
        update_mosh_interval(true, &mut was_active, &mut generation, &mut retained);
        assert!(retained.is_some(), "a continuously armed interval retains");

        update_mosh_interval(false, &mut was_active, &mut generation, &mut retained);
        assert!(
            retained.is_none(),
            "linked dry clears the narrower codec interval even though visual epoch stays 41"
        );
        update_mosh_interval(true, &mut was_active, &mut generation, &mut retained);
        assert!(
            retained.is_none(),
            "re-entry stays on the clean composite until a fresh worker result"
        );
        assert_ne!(generation, pre_dry_generation);
        assert!(
            !mosh_sample_is_current(
                visual_epoch,
                pre_dry_generation,
                visual_epoch,
                generation,
                true,
            ),
            "a readback or worker result sampled before dry cannot resurface after re-entry"
        );
        assert!(mosh_sample_is_current(
            visual_epoch,
            generation,
            visual_epoch,
            generation,
            true,
        ));
    }

    #[test]
    fn selective_vhs_generation_reset_cannot_erase_temporal_or_sync_memory() {
        let renderer_source = include_str!("renderer/state.rs");
        let start = renderer_source
            .find("pub(crate) fn reset_output_pipeline_generation")
            .expect("output-only generation reset exists");
        let end = renderer_source[start..]
            .find("fn invalidate_async_output_generation")
            .map(|offset| start + offset)
            .expect("output-only reset delegates to async invalidation");
        let method = &renderer_source[start..end];
        assert!(method.contains("invalidate_async_output_generation"));
        assert!(!method.contains("temporal_state"));
        assert!(!method.contains("sync_latch"));

        let live_source = include_str!("main.rs");
        let (production, _tests) = live_source
            .split_once("mod app_state_tests")
            .expect("main.rs carries its test module");
        assert!(production.contains("renderer.reset_output_pipeline_generation();"));
        assert!(!production.contains("renderer.reset_visual_generation();"));
    }

