    #[test]
    fn beat_latched_capture_preserves_fader_order_and_is_never_coalesced() {
        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state);
        app.queue_quantized_action(web::state::WebAction::SetMorph { value: 0.2 });
        app.queue_quantized_action(web::state::WebAction::MorphCapture {
            slot: "a".into(),
            stack_revision: Some(app.layer_stack_revision),
            composition_revision: Some(app.composition_revision),
        });
        app.queue_quantized_action(web::state::WebAction::SetMorph { value: 0.8 });
        app.queue_quantized_action(web::state::WebAction::MorphCapture {
            slot: "a".into(),
            stack_revision: Some(app.layer_stack_revision),
            composition_revision: Some(app.composition_revision),
        });

        assert_eq!(app.quantized_actions.len(), 4);
        assert!(matches!(
            app.quantized_actions.as_slice(),
            [
                web::state::WebAction::SetMorph { value: first },
                web::state::WebAction::MorphCapture { .. },
                web::state::WebAction::SetMorph { value: second },
                web::state::WebAction::MorphCapture { .. },
            ] if *first == 0.2 && *second == 0.8
        ));

        app.bump_layer_stack_revision();
        assert!(app
            .quantized_actions
            .iter()
            .all(|action| !matches!(action, web::state::WebAction::MorphCapture { .. })));
    }

    #[test]
    fn audio_clip_loading_freezes_the_internal_program_without_changing_master_pause() {
        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state);
        let start = Instant::now();
        app.mod_matrix.clock.set_bpm_at(120.0, start);

        let load_start = start + Duration::from_secs(2);
        let beat_at_load = app.mod_matrix.clock.beat(load_start);
        app.set_audio_clip_blocks_program_at(true, load_start);

        assert!(
            !app.master_paused,
            "the browser Pause state stays authoritative"
        );
        assert!(app.program_transport_paused());
        assert!(app.mod_matrix.clock.is_paused());

        let slow_decode_completion = load_start + Duration::from_secs(45);
        assert_eq!(
            app.mod_matrix.clock.beat(slow_decode_completion),
            beat_at_load,
            "decoder latency must not advance beat/LFO/morph phase"
        );
        assert_eq!(
            app.program_clock
                .tick(Duration::from_secs(45), app.program_transport_paused()),
            (Duration::ZERO, 0.0),
            "decoder latency must not advance shader, audio, temporal, or NTSC time"
        );

        app.set_audio_clip_blocks_program_at(false, slow_decode_completion);
        assert!(!app.program_transport_paused());
        assert!(!app.mod_matrix.clock.is_paused());
        assert!((app.mod_matrix.clock.beat(slow_decode_completion) - beat_at_load).abs() < 1e-9);

        let first_render = slow_decode_completion + Duration::from_millis(16);
        assert!((app.mod_matrix.clock.beat(first_render) - (beat_at_load + 0.032)).abs() < 1e-6);
    }

    #[test]
    fn master_revert_is_complete_but_preserves_transport_inputs_and_layer_latches() {
        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state);
        let master_node = app
            .master_rack
            .insert(
                1,
                visual_rack::RuntimeVisualNodeKind::DigitalColor(
                    visual_rack::DigitalColorParams::default(),
                ),
            )
            .expect("custom master node");
        let preserved_next_node_id = app.master_rack.next_node_id_raw();
        let group_id = app
            .composition
            .insert_empty_group(composition::GroupName::new("preserved group").unwrap(), 0)
            .expect("empty creative group");
        {
            let group = app.composition.group_mut(group_id).unwrap();
            group.opacity = 0.37;
            group.bus = composition::BusAssignment::B;
            group
                .rack
                .push(visual_rack::RuntimeVisualNodeKind::Shift(
                    visual_rack::ShiftParams::default(),
                ))
                .expect("custom group rack");
        }
        let preserved_composition = app.composition.clone();
        let composition_revision_before = app.composition_revision;
        app.master_effects.brightness = 0.8;
        app.master_transform.skew_deg = 12.0;
        app.ntsc_params.enabled = true;
        app.temporal_params.feedback = 0.9;
        app.mod_matrix.clock.set_bpm(147.0);
        app.mod_matrix.audio_enabled = true;
        app.mod_matrix.audio_gain = 2.25;
        app.mod_matrix.audio_device = "preserved input".to_string();
        app.mod_matrix.midi_enabled = true;
        app.mod_matrix.midi_ccs = [21, 22, 23, 24];
        app.mod_matrix.routings.push(modulation::Routing::new(
            modulation::ModSource::Lfo(0),
            "brightness",
            1.0,
        ));
        let slot = morph::MorphSlot::capture(
            &app.master_effects,
            &app.master_transform,
            &app.ntsc_params,
            &app.temporal_params,
            &[],
        );
        app.morph.a = Some(slot.clone());
        app.morph.b = Some(slot);
        app.morph.start_glide(1.0, 8.0, 0.0);
        app.master_paused = true;
        app.selective_transition_holding = true;
        app.selective_hold_snapshot_valid = true;
        app.selective_hold_spout_barrier_epoch = Some(17);
        app.selective_hold_spout_readback_epoch = Some(17);
        app.blackout = true;
        app.blackout_presented = false;
        app.quantized_actions = vec![
            web::state::WebAction::SetParam {
                param: "contrast".to_string(),
                value: serde_json::json!(0.5),
            },
            web::state::WebAction::SetNtscParam {
                param: "snow_intensity".to_string(),
                value: serde_json::json!(0.8),
            },
            web::state::WebAction::SetVisualNodeParam {
                scope: web::state::CreativeScopeSnapshot::Master,
                node_id: master_node.get().to_string(),
                node_kind: "digital_color".to_string(),
                param: "brightness".to_string(),
                value: serde_json::json!(0.4),
                composition_revision: app.composition_revision,
            },
            web::state::WebAction::SetLayerEffect {
                index: 0,
                layer_id: None,
                param: "vignette".to_string(),
                value: serde_json::json!(0.4),
            },
        ];
        let old_epoch = app.visual_epoch;

        assert!(app.revert_master_visual_state());

        assert_eq!(app.master_effects.brightness, 0.0);
        assert_eq!(app.master_transform, spatial::SpatialTransform::default());
        assert_eq!(app.ntsc_params, ntsc::NtscParams::default());
        assert_eq!(app.temporal_params.feedback, 0.0);
        assert!(app.mod_matrix.routings.is_empty());
        assert!(app.morph.a.is_none());
        assert!(app.morph.b.is_none());
        assert!(app.morph.glide.is_none());
        assert_eq!(app.quantized_actions.len(), 1);
        assert!(matches!(
            app.quantized_actions[0],
            web::state::WebAction::SetLayerEffect { .. }
        ));
        assert!(app.master_rack.is_exact_legacy(LegacyRackScope::Master));
        assert_eq!(
            app.master_rack.next_node_id_raw(),
            preserved_next_node_id,
            "reset must not recycle stable node IDs"
        );
        assert_eq!(app.composition, preserved_composition);
        assert_eq!(
            app.composition_revision,
            composition_revision_before + 1,
            "removing custom master topology is one composition transaction"
        );
        assert_eq!(app.mod_matrix.clock.bpm, 147.0);
        assert!(app.mod_matrix.audio_enabled);
        assert_eq!(app.mod_matrix.audio_gain, 2.25);
        assert_eq!(app.mod_matrix.audio_device, "preserved input");
        assert!(app.mod_matrix.midi_enabled);
        assert_eq!(app.mod_matrix.midi_ccs, [21, 22, 23, 24]);
        assert!(app.master_paused);
        assert!(!app.selective_transition_holding);
        assert!(!app.selective_hold_snapshot_valid);
        assert!(app.selective_hold_spout_barrier_epoch.is_none());
        assert!(app.selective_hold_spout_readback_epoch.is_none());
        assert!(app.blackout);
        assert!(app.blackout_presented);
        assert_ne!(app.visual_epoch, old_epoch);

        let settled_revision = app.composition_revision;
        assert!(app.revert_master_visual_state());
        assert_eq!(
            app.composition_revision, settled_revision,
            "an already-synthetic master reset has no topology revision"
        );
        assert_eq!(app.composition, preserved_composition);
    }

    #[test]
    fn reset_actions_dispatch_from_json_with_versioned_scope() {
        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state);
        app.master_effects.resolution = [1920.0, 1080.0];
        app.master_effects.brightness = 0.8;
        app.master_effects.random_seed = 41;
        app.master_transform.rotation_deg = 31.0;
        app.ntsc_params.enabled = true;
        app.ntsc_params.snow_intensity = 0.6;
        app.temporal_params.feedback = 0.9;
        app.mod_matrix.routings.push(modulation::Routing::new(
            modulation::ModSource::Lfo(0),
            "brightness",
            1.0,
        ));
        let slot = morph::MorphSlot::capture(
            &app.master_effects,
            &app.master_transform,
            &app.ntsc_params,
            &app.temporal_params,
            &[],
        );
        app.morph.a = Some(slot.clone());
        app.morph.b = Some(slot);
        app.quantized_actions.push(web::state::WebAction::SetParam {
            param: "contrast".to_string(),
            value: serde_json::json!(0.5),
        });
        let initial_epoch = app.visual_epoch;

        let legacy: web::state::WebAction =
            serde_json::from_str(r#"{"action":"reset_fx"}"#).unwrap();
        app.handle_web_action(legacy);

        assert_eq!(app.master_effects.brightness, 0.0);
        assert_eq!(app.master_effects.random_seed, 0);
        assert_eq!(app.master_effects.resolution, [1920.0, 1080.0]);
        assert_eq!(app.master_transform.rotation_deg, 31.0);
        assert!(app.ntsc_params.enabled);
        assert_eq!(app.ntsc_params.snow_intensity, 0.6);
        assert_eq!(app.temporal_params.feedback, 0.9);
        assert_eq!(app.mod_matrix.routings.len(), 1);
        assert!(app.morph.active());
        assert_eq!(app.quantized_actions.len(), 1);
        assert_eq!(app.visual_epoch, initial_epoch);

        let broad: web::state::WebAction =
            serde_json::from_str(r#"{"action":"reset_visual_program"}"#).unwrap();
        app.handle_web_action(broad);

        assert_eq!(app.master_transform, spatial::SpatialTransform::default());
        assert_eq!(app.ntsc_params, ntsc::NtscParams::default());
        assert_eq!(
            app.temporal_params.feedback,
            effects::params::TemporalParams::default().feedback
        );
        assert!(app.mod_matrix.routings.is_empty());
        assert!(!app.morph.active());
        assert!(app.quantized_actions.is_empty());
        assert_ne!(app.visual_epoch, initial_epoch);
    }

    // ---- S6 preview transform gizmo --------------------------------------

    /// Drive one gizmo drag end to end through the host's own dispatcher.
    ///
    /// It deliberately goes through `apply_transform_gizmo_event`, the same
    /// entry point the egui frame calls, rather than poking the drag state
    /// directly: the laws under test live in the host wiring, not in the
    /// portable module that already has its own goldens.
    fn drive_gizmo_drag(
        app: &mut App,
        grab: [f32; 2],
        moves: &[[f32; 2]],
        modifiers: transform_gizmo::GizmoModifiers,
    ) {
        app.apply_transform_gizmo_event(transform_gizmo::GizmoPointerEvent {
            phase: transform_gizmo::GizmoPhase::Begin,
            output_uv: grab,
            modifiers,
        });
        for step in moves {
            app.apply_transform_gizmo_event(transform_gizmo::GizmoPointerEvent {
                phase: transform_gizmo::GizmoPhase::Move,
                output_uv: *step,
                modifiers,
            });
        }
        app.apply_transform_gizmo_event(transform_gizmo::GizmoPointerEvent {
            phase: transform_gizmo::GizmoPhase::End,
            output_uv: moves.last().copied().unwrap_or(grab),
            modifiers,
        });
    }

    /// Where the master scope's move handle sits, in composition-output UV.
    ///
    /// Translation is a point handle, not the footprint body: the preview is
    /// also the gesture-etch surface, and a body-sized target would claim every
    /// drag over the image.
    fn gizmo_move_handle(app: &App) -> [f32; 2] {
        app.transform_gizmo_frame(transform_gizmo::GizmoScope::Master)
            .expect("the master transform is renderable")
            .handle_position(transform_gizmo::GizmoHandle::Translate)
            .expect("the move handle is placed")
    }

    fn gizmo_test_app() -> App {
        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state);
        // No selection means the master scope, which is the only scope an app
        // fixture can reach without a real decoded media source.
        app.selected_layer = None;
        app
    }

    /// The delivery claim, in one fixture: a drag really moves the authored
    /// transform, the identical numeric edit produces byte-identical authored
    /// state, and a drag that moves nothing changes nothing.
    ///
    /// Byte identity here is structural rather than lucky — both paths reach
    /// `apply_spatial_transform_edit` with the same param and the same value —
    /// and that is exactly the property worth pinning, because the moment a
    /// gizmo grows its own authoring branch this fixture fails.
    #[test]
    fn a_gizmo_drag_and_the_identical_numeric_edit_author_byte_identical_state() {
        let mut app = gizmo_test_app();
        let untouched = app.master_transform;
        assert_eq!(untouched, spatial::SpatialTransform::default());

        let grab = gizmo_move_handle(&app);
        drive_gizmo_drag(
            &mut app,
            grab,
            &[[grab[0] + 0.1, grab[1] - 0.05]],
            transform_gizmo::GizmoModifiers::NONE,
        );
        let dragged = app.master_transform;
        assert_ne!(
            dragged, untouched,
            "a drag must actually move the authored transform"
        );

        // The same values, authored the way the browser numeric editor does.
        let mut numeric = gizmo_test_app();
        for (param, value) in [
            ("position_x", f64::from(dragged.position[0])),
            ("position_y", f64::from(dragged.position[1])),
        ] {
            numeric.handle_web_action_inner_with_feedback_from_origin(
                web::state::WebAction::SetMasterTransform {
                    param: param.to_string(),
                    value: serde_json::json!(value),
                },
                action_correlation::ActionSourceClass::Browser,
            );
        }
        assert_eq!(
            numeric.master_transform, dragged,
            "the gizmo must author exactly what the numeric path authors"
        );

        // A gesture that never moves the pointer authors nothing.
        let mut still = gizmo_test_app();
        let grab = gizmo_move_handle(&still);
        drive_gizmo_drag(
            &mut still,
            grab,
            &[grab],
            transform_gizmo::GizmoModifiers::NONE,
        );
        assert_eq!(
            still.master_transform, untouched,
            "a no-op gesture must leave the authored transform byte-identical"
        );
    }

    /// One drag is exactly one manual-history entry, no matter how many
    /// intermediate moves it carried.
    #[test]
    fn one_gizmo_drag_is_exactly_one_undo_entry() {
        let mut app = gizmo_test_app();
        let before = app.manual_history.metrics().undo_depth;

        let grab = gizmo_move_handle(&app);
        let moves: Vec<[f32; 2]> = (1..=64)
            .map(|step| [grab[0] + step as f32 * 0.002, grab[1]])
            .collect();
        drive_gizmo_drag(
            &mut app,
            grab,
            &moves,
            transform_gizmo::GizmoModifiers::NONE,
        );

        let metrics = app.manual_history.metrics();
        assert!(
            !metrics.gesture_open,
            "the drag must close its own transaction"
        );
        assert_eq!(
            metrics.undo_depth,
            before + 1,
            "sixty-four moves must cost the bounded stack exactly one entry"
        );
        assert!(app.transform_gizmo_drag.is_none());
    }

    /// A drag that authors nothing keeps the bounded stack untouched, so an
    /// accidental click is not an undo step.
    #[test]
    fn a_gizmo_drag_that_authors_nothing_records_no_history_entry() {
        let mut app = gizmo_test_app();
        let before = app.manual_history.metrics().undo_depth;
        let grab = gizmo_move_handle(&app);
        drive_gizmo_drag(
            &mut app,
            grab,
            &[grab],
            transform_gizmo::GizmoModifiers::NONE,
        );
        assert_eq!(app.manual_history.metrics().undo_depth, before);
    }

    /// Escape's two meanings, and the difference between them is observable.
    #[test]
    fn escape_cancels_before_a_commit_and_undoes_after_one() {
        // Before any commit: the captured transform is restored and nothing
        // reaches the bounded stack.
        let mut app = gizmo_test_app();
        let untouched = app.master_transform;
        let depth = app.manual_history.metrics().undo_depth;
        app.apply_transform_gizmo_event(transform_gizmo::GizmoPointerEvent {
            phase: transform_gizmo::GizmoPhase::Begin,
            output_uv: gizmo_move_handle(&app),
            modifiers: transform_gizmo::GizmoModifiers::NONE,
        });
        assert!(app.transform_gizmo_drag.is_some());
        assert!(app.manual_history.metrics().gesture_open);
        assert_eq!(
            app.transform_gizmo_escape(),
            Some(ActionLifecycleOutcome::Coalesced),
            "an unchanged open boundary is consumed without claiming a frame",
        );
        assert!(app.transform_gizmo_drag.is_none());
        assert!(!app.manual_history.metrics().gesture_open);
        assert_eq!(app.manual_history.metrics().undo_depth, depth);
        assert_eq!(app.master_transform, untouched);

        // After a commit: the program already moved, so a cancel would be a
        // lie. The gesture closes and an ordinary undo runs.
        let mut app = gizmo_test_app();
        let untouched = app.master_transform;
        let grab = gizmo_move_handle(&app);
        app.apply_transform_gizmo_event(transform_gizmo::GizmoPointerEvent {
            phase: transform_gizmo::GizmoPhase::Begin,
            output_uv: grab,
            modifiers: transform_gizmo::GizmoModifiers::NONE,
        });
        app.apply_transform_gizmo_event(transform_gizmo::GizmoPointerEvent {
            phase: transform_gizmo::GizmoPhase::Move,
            output_uv: [grab[0] + 0.15, grab[1] - 0.15],
            modifiers: transform_gizmo::GizmoModifiers::NONE,
        });
        assert_ne!(app.master_transform, untouched, "the drag must have moved");
        assert!(app
            .transform_gizmo_drag
            .is_some_and(|drag| drag.has_committed()));
        assert_eq!(
            app.transform_gizmo_escape(),
            Some(ActionLifecycleOutcome::Applied),
            "undoing a committed visual drag is a real applied mutation",
        );
        assert!(app.transform_gizmo_drag.is_none());
        assert_eq!(
            app.master_transform, untouched,
            "an undo after a commit still returns the authored transform"
        );

        // Outside a drag the gizmo consumes nothing, so Escape keeps every
        // other meaning it already had.
        let mut idle = gizmo_test_app();
        assert_eq!(idle.transform_gizmo_escape(), None);
    }

    /// A topology edit mid-drag abandons the gesture instead of delivering the
    /// remaining delta to whatever now occupies that position.
    #[test]
    fn a_topology_change_during_a_drag_aborts_it_without_retargeting() {
        let mut app = gizmo_test_app();
        let depth = app.manual_history.metrics().undo_depth;
        app.apply_transform_gizmo_event(transform_gizmo::GizmoPointerEvent {
            phase: transform_gizmo::GizmoPhase::Begin,
            output_uv: gizmo_move_handle(&app),
            modifiers: transform_gizmo::GizmoModifiers::NONE,
        });
        assert!(app.transform_gizmo_drag.is_some());
        assert!(app.manual_history.metrics().gesture_open);

        // Every topology edit — add, remove, reorder, patch apply — crosses
        // this one barrier.
        app.bump_layer_stack_revision();

        assert!(app.transform_gizmo_drag.is_none(), "the drag must abort");
        assert!(
            !app.manual_history.metrics().gesture_open,
            "the open checkpoint described a program that no longer exists"
        );
        assert_eq!(
            app.manual_history.metrics().undo_depth,
            depth,
            "an aborted gesture is abandoned, not committed"
        );
        assert!(app.transform_gizmo_status.contains("aborted"));

        // A stale Move after the abort authors nothing at all.
        let after_abort = app.master_transform;
        app.apply_transform_gizmo_event(transform_gizmo::GizmoPointerEvent {
            phase: transform_gizmo::GizmoPhase::Move,
            output_uv: [0.9, 0.1],
            modifiers: transform_gizmo::GizmoModifiers::NONE,
        });
        assert_eq!(app.master_transform, after_abort);
    }

    /// Nudges take the ordinary manual-history boundary, and are refused while
    /// a drag owns the scope.
    #[test]
    fn keyboard_nudges_follow_the_documented_law_and_yield_to_an_open_drag() {
        let mut app = gizmo_test_app();
        let depth = app.manual_history.metrics().undo_depth;
        assert!(app.apply_transform_gizmo_nudge(
            transform_gizmo::GizmoNudge::Right,
            transform_gizmo::GizmoModifiers::NONE,
        ));
        assert!(
            (app.master_transform.position[0] - transform_gizmo::NUDGE_STEP).abs() <= 1.0e-6,
            "an unmodified nudge moves exactly one step"
        );
        assert_eq!(app.manual_history.metrics().undo_depth, depth + 1);

        // Shift is the coarse step and Alt the fine one, both from the value
        // the previous nudge left behind.
        let before = app.master_transform.position[0];
        app.apply_transform_gizmo_nudge(
            transform_gizmo::GizmoNudge::Right,
            transform_gizmo::GizmoModifiers {
                shift: true,
                alt: false,
            },
        );
        assert!(
            (app.master_transform.position[0] - before - transform_gizmo::NUDGE_COARSE_STEP).abs()
                <= 1.0e-6
        );

        // An open drag owns the scope; a nudge into it is refused rather than
        // interleaved with the drag's transaction.
        app.apply_transform_gizmo_event(transform_gizmo::GizmoPointerEvent {
            phase: transform_gizmo::GizmoPhase::Begin,
            output_uv: gizmo_move_handle(&app),
            modifiers: transform_gizmo::GizmoModifiers::NONE,
        });
        let held = app.master_transform;
        assert!(!app.apply_transform_gizmo_nudge(
            transform_gizmo::GizmoNudge::Left,
            transform_gizmo::GizmoModifiers::NONE,
        ));
        assert_eq!(app.master_transform, held);
    }

    /// The gizmo cannot be painted on an audience surface, and single-monitor
    /// Output removes it by the same predicate that removes every other native
    /// control.
    #[test]
    fn the_gizmo_permit_and_the_native_control_predicate_agree() {
        assert!(show_transform_gizmo(false));
        assert!(!show_transform_gizmo(true));
        // Every native control answers from one predicate, so they cannot
        // drift into disagreeing about when the preview is safe to draw on.
        assert_eq!(show_transform_gizmo(true), show_native_recovery_strip(true));
        assert_eq!(
            show_transform_gizmo(false),
            show_native_recovery_strip(false)
        );
        assert_eq!(
            show_transform_gizmo(true),
            show_native_gesture_surface(true)
        );
        assert_eq!(show_transform_gizmo(true), show_stage_editor_health(true));
        assert_eq!(show_transform_gizmo(true), show_editor_panel(true, true));

        // And the permit refuses exactly the same cases.
        assert!(transform_gizmo::preview_gizmo_permit(
            &stage_map::StageSurface::EditorPreview,
            false
        )
        .is_some());
        assert!(transform_gizmo::preview_gizmo_permit(
            &stage_map::StageSurface::EditorPreview,
            true
        )
        .is_none());
        for surface in [
            stage_map::StageSurface::Composite,
            stage_map::StageSurface::Audience,
            stage_map::StageSurface::Spout,
            stage_map::StageSurface::Record,
            stage_map::StageSurface::Export,
        ] {
            assert!(transform_gizmo::preview_gizmo_permit(&surface, false).is_none());
        }
    }

    /// A gizmo drag onto Morph-owned state transfers ownership exactly as a
    /// numeric edit does.
    ///
    /// This is the load-bearing consequence of dispatching real transform
    /// actions rather than mutating the field directly: `handle_web_action_inner`
    /// runs `release_active_morph_for_manual_edit` first, so the engaged A/B
    /// pair materializes and clears before the drag's first value lands. A
    /// gizmo that wrote `self.master_transform` itself would author underneath
    /// an engaged pair and snap back at the next materialization.
    #[test]
    fn a_gizmo_drag_releases_morph_ownership_before_authoring() {
        let mut app = gizmo_test_app();
        app.morph.a = Some(morph::MorphSlot {
            master_transform: Some(spatial::SpatialTransform::default()),
            ..morph::MorphSlot::default()
        });
        app.morph.b = Some(morph::MorphSlot {
            master_transform: Some(spatial::SpatialTransform::default()),
            ..morph::MorphSlot::default()
        });
        assert!(app.morph.active());
        assert!(
            app.morph.controls_master_transform(),
            "the fixture must really own the master transform"
        );

        let grab = gizmo_move_handle(&app);
        drive_gizmo_drag(
            &mut app,
            grab,
            &[[grab[0] + 0.15, grab[1] - 0.1]],
            transform_gizmo::GizmoModifiers::NONE,
        );

        assert!(
            !app.morph.active(),
            "the drag must transfer Morph ownership rather than author under it"
        );
        assert_ne!(app.master_transform, spatial::SpatialTransform::default());
    }

    /// A drag never activates the spatial path by being looked at, and the
    /// master scope's frame is derived with the exact dimension convention the
    /// render path uses.
    #[test]
    fn hovering_a_gizmo_leaves_a_legacy_patch_on_the_historical_sample() {
        let app = gizmo_test_app();
        let scope = app
            .transform_gizmo_scope()
            .expect("no selection resolves to the master scope");
        assert_eq!(scope, transform_gizmo::GizmoScope::Master);
        let frame = app
            .transform_gizmo_frame(scope)
            .expect("the default master transform is renderable");
        assert!(
            !frame.uniforms().is_spatially_active(),
            "the fixture starts on the exact historical sample"
        );
        for probe in [[0.0, 0.0], [0.5, 0.5], [1.0, 1.0], [0.25, 0.75]] {
            let _ = frame.hit_test(probe);
        }
        assert_eq!(app.master_transform, spatial::SpatialTransform::default());
        assert!(!app
            .transform_gizmo_frame(scope)
            .expect("still renderable")
            .uniforms()
            .is_spatially_active());
    }

    #[test]
    fn native_recovery_actions_are_absolute_and_work_without_a_browser() {
        let web_state = WebState::new().expect("test token");
        assert_eq!(web_state.tx.receiver_count(), 0);
        let server = web_state.control_server_info();
        assert_eq!(server.loopback_ipv4, ControlListenerStatus::Stopped);
        assert_eq!(server.loopback_ipv6, ControlListenerStatus::Stopped);
        assert_eq!(server.lan_tls, ControlListenerStatus::Stopped);
        let queued = web_state.envelope_for_test(web::state::WebAction::SetParam {
            param: "contrast".to_string(),
            value: serde_json::json!(0.25),
        });
        web_state
            .actions
            .try_lock()
            .expect("test action queue")
            .push(queued);

        let mut app = App::new(None, None, web_state.clone());
        app.master_effects.brightness = 0.8;
        app.ntsc_params.enabled = true;
        app.temporal_params.feedback = 0.9;
        app.mod_matrix.routings.push(modulation::Routing::new(
            modulation::ModSource::Lfo(0),
            "brightness",
            1.0,
        ));

        app.apply_native_recovery_action(NativeRecoveryAction::SetProgramFrozen(true));
        app.apply_native_recovery_action(NativeRecoveryAction::SetProgramFrozen(true));
        assert!(app.master_paused);
        assert!(app.mod_matrix.clock.is_paused());

        app.apply_native_recovery_action(NativeRecoveryAction::SetBlackout(true));
        let blackout_epoch = app.visual_epoch;
        app.apply_native_recovery_action(NativeRecoveryAction::SetBlackout(true));
        assert!(app.blackout);
        assert_eq!(app.visual_epoch, blackout_epoch);

        app.apply_native_recovery_action(NativeRecoveryAction::RevertVisualProgram);
        assert_eq!(app.master_effects.brightness, 0.0);
        assert_eq!(app.ntsc_params, ntsc::NtscParams::default());
        assert_eq!(app.temporal_params.feedback, 0.0);
        assert!(app.mod_matrix.routings.is_empty());
        assert!(app.master_paused, "broad Revert preserves transport");
        assert!(app.blackout, "broad Revert preserves the safety cut");
        assert_eq!(
            web_state
                .actions
                .try_lock()
                .expect("test action queue")
                .len(),
            1,
            "native controls do not depend on or mutate browser ingress"
        );
    }

    #[test]
    fn web_publication_is_absent_without_receivers_and_newest_only_with_one() {
        assert!(!App::web_action_requires_full_publication(
            &web::state::WebAction::Gyro {
                alpha: 0.0,
                beta: 0.0,
                gamma: 0.0,
            }
        ));
        assert!(App::web_action_requires_full_publication(
            &web::state::WebAction::ResetFx
        ));
        let web_state = WebState::new().expect("web state");
        let mut app = App::new(None, None, web_state.clone());
        app.master_effects.brightness = 0.625;

        assert_eq!(web_state.tx.receiver_count(), 0);
        app.push_web_state();
        assert_eq!(web_state.serialized_publications_for_test(), 0);

        let mut receiver = web_state.tx.subscribe();
        let before_generation = web_state.request_snapshot();
        app.push_web_state();
        assert_eq!(web_state.serialized_publications_for_test(), 1);
        assert!(web_state.full_snapshot_generation() > before_generation);
        assert!(receiver.has_changed().unwrap());
        let first_wire = receiver.borrow_and_update().clone();
        let first: web::state::AppSnapshot = serde_json::from_str(first_wire.as_ref()).unwrap();
        assert_eq!(first.effects.brightness, 0.625);
        assert_eq!(first.wire_version, 2);
        let _other_receivers = [
            web_state.tx.subscribe(),
            web_state.tx.subscribe(),
            web_state.tx.subscribe(),
        ];
        assert_eq!(web_state.tx.receiver_count(), 4);

        // An unchanged authored base emits only the explicit operational and
        // telemetry domains. The separately cached full state remains the
        // connection base even though watch now retains this newer live value.
        app.web_last_publish_at = Instant::now().checked_sub(Duration::from_secs(1)).unwrap();
        app.push_web_state();
        assert_eq!(web_state.serialized_publications_for_test(), 2);
        let live_wire = receiver.borrow_and_update().clone();
        let live: web::state::WebLiveSnapshot = serde_json::from_str(live_wire.as_ref()).unwrap();
        assert_eq!(live.msg_type, "live");
        assert_eq!(live.authored_revision, first.authored_revision);
        let live_value: serde_json::Value = serde_json::from_str(live_wire.as_ref()).unwrap();
        let live_object = live_value.as_object().unwrap();
        assert!(!live_object.contains_key("layers"));
        assert!(!live_object.contains_key("effects"));
        assert_eq!(web_state.last_full_snapshot().as_ref(), first_wire.as_ref());

        // A new accepted action revision bypasses the meter cadence and emits
        // a complete authored state exactly once for all four browsers.
        app.master_effects.brightness = 0.75;
        app.web_authored_mutation_counter = app.web_authored_mutation_counter.saturating_add(1);
        app.push_web_state();
        assert_eq!(web_state.serialized_publications_for_test(), 3);
        let revised = receiver.borrow_and_update().clone();
        let revised: web::state::AppSnapshot = serde_json::from_str(revised.as_ref()).unwrap();
        assert_eq!(revised.effects.brightness, 0.75);
        assert!(revised.authored_revision > first.authored_revision);

        // An explicit reconnect/full-state request also bypasses cadence even
        // when no authored revision changed.
        app.master_effects.brightness = 0.875;
        app.push_web_state();
        assert_eq!(web_state.serialized_publications_for_test(), 3);
        web_state.request_snapshot();
        app.push_web_state();
        assert_eq!(web_state.serialized_publications_for_test(), 4);
        assert!(receiver.has_changed().unwrap());
        let latest = receiver.borrow_and_update().clone();
        let latest: web::state::AppSnapshot = serde_json::from_str(latest.as_ref()).unwrap();
        assert_eq!(latest.effects.brightness, 0.875);
        assert!(!receiver.has_changed().unwrap());
    }

    #[test]
    fn native_recovery_authored_actions_record_and_undo_manual_history() {
        let mut app = App::new(None, None, WebState::new().expect("test token"));
        app.recovery_writer = None;
        let initial_depth = app.manual_history.metrics().undo_depth;

        app.apply_native_recovery_action(NativeRecoveryAction::SetProgramFrozen(true));
        app.apply_native_recovery_action(NativeRecoveryAction::SetProgramFrozen(true));
        assert!(app.master_paused);
        assert_eq!(app.manual_history.metrics().undo_depth, initial_depth + 1);
        app.restore_history_direction(false);
        assert!(!app.master_paused);

        app.master_effects.brightness = 0.8;
        app.apply_native_recovery_action(NativeRecoveryAction::RevertVisualProgram);
        assert_eq!(app.master_effects.brightness, 0.0);
        assert_eq!(app.manual_history.metrics().undo_depth, initial_depth + 1);
        app.restore_history_direction(false);
        assert_eq!(app.master_effects.brightness, 0.8);
    }

    #[test]
    fn native_modal_reanchors_program_timing_without_changing_freeze_state() {
        let mut app = App::new(None, None, WebState::new().expect("test token"));
        let modal_started = Instant::now();
        let beat_before = app.mod_matrix.clock.beat(modal_started);
        app.mod_matrix.clock.set_paused(true, modal_started);

        let modal_finished = modal_started + Duration::from_secs(45);
        app.finish_native_modal(false, modal_finished);

        assert!(!app.master_paused);
        assert!(!app.mod_matrix.clock.is_paused());
        assert_eq!(app.frame_pacer.last_accepted_at(), modal_finished);
        assert!((app.mod_matrix.clock.beat(modal_finished) - beat_before).abs() < 1.0e-9);
        assert!(
            app.mod_matrix
                .clock
                .beat(modal_finished + Duration::from_millis(10))
                > beat_before
        );
    }

    #[test]
    fn folder_switch_clears_caches_and_native_rescan_discovers_new_media() {
        let unique = format!(
            "collide-o-scope-p3-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("system time")
                .as_nanos()
        );
        let folder = std::env::temp_dir().join(unique);
        std::fs::create_dir_all(&folder).expect("create test library");

        let web_state = WebState::new().expect("test token");
        web_state
            .thumbnails
            .write()
            .expect("thumbnail cache")
            .insert("same-name.png".to_string(), vec![1]);
        web_state
            .preview_frames
            .write()
            .expect("preview cache")
            .insert("same-name.png".to_string(), vec![vec![2]]);
        let mut app = App::new(None, None, web_state.clone());

        app.set_library_folder(folder.clone());
        assert!(web_state
            .thumbnails
            .read()
            .expect("thumbnail cache")
            .is_empty());
        assert!(web_state
            .preview_frames
            .read()
            .expect("preview cache")
            .is_empty());
        assert_eq!(
            web_state
                .library_folder
                .read()
                .expect("shared library")
                .as_ref(),
            Some(&folder)
        );

        let added = folder.join("new-visual.png");
        std::fs::write(&added, []).expect("create visual fixture");
        // Mark the basename cached so this focused scan test does not launch
        // ffmpeg for an intentionally empty extension-only fixture.
        web_state
            .thumbnails
            .write()
            .expect("thumbnail cache")
            .insert("new-visual.png".to_string(), Vec::new());
        app.apply_native_recovery_action(NativeRecoveryAction::RescanLibrary);
        let deadline = Instant::now() + Duration::from_secs(2);
        while app.library_files.as_slice() != std::slice::from_ref(&added) {
            app.poll_library_index();
            assert!(
                Instant::now() < deadline,
                "asynchronous library scan did not publish"
            );
            std::thread::yield_now();
        }
        assert_eq!(app.library_files, vec![added]);

        std::fs::remove_dir_all(folder).expect("remove test library");
    }

    #[test]
    fn stale_library_workers_cannot_repopulate_current_caches() {
        let web_state = WebState::new().expect("test token");
        let old_generation = web_state.begin_library_generation();
        assert!(publish_thumbnail_if_current(
            &web_state,
            old_generation,
            "clip.png".to_string(),
            vec![1]
        ));
        assert!(publish_preview_if_current(
            &web_state,
            old_generation,
            "clip.png".to_string(),
            vec![vec![1]]
        ));

        let current_generation = web_state.begin_library_generation();
        web_state.clear_library_media_caches();

        assert!(!publish_thumbnail_if_current(
            &web_state,
            old_generation,
            "clip.png".to_string(),
            vec![2]
        ));
        assert!(!publish_preview_if_current(
            &web_state,
            old_generation,
            "clip.png".to_string(),
            vec![vec![2]]
        ));
        assert!(publish_thumbnail_if_current(
            &web_state,
            current_generation,
            "clip.png".to_string(),
            vec![3]
        ));
        assert_eq!(
            web_state
                .thumbnails
                .read()
                .expect("thumbnail cache")
                .get("clip.png"),
            Some(&vec![3])
        );
        assert!(web_state
            .preview_frames
            .read()
            .expect("preview cache")
            .is_empty());
    }

    #[test]
    fn patch_generation_discards_old_latches_and_advances_epochs() {
        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state);
        let timing_anchor = Instant::now();
        app.mod_matrix.pad_config.spring_enabled = true;
        app.mod_matrix.pad_config.spring_rate = 4.0;
        app.mod_matrix.set_pad(1.0, 0.0, false);
        app.mod_matrix.update(timing_anchor);
        app.mod_matrix.current_beat = 9.25;
        let clock_probe = timing_anchor + Duration::from_secs(1);
        let clock_beat_before = app.mod_matrix.clock.beat(clock_probe);
        app.quantized_actions.push(web::state::WebAction::SetParam {
            param: "brightness".to_string(),
            value: serde_json::json!(0.75),
        });
        let queued = app
            .web_state
            .envelope_for_test(web::state::WebAction::RemoveLayer {
                index: 0,
                layer_id: None,
            });
        app.web_state.actions.blocking_lock().push(queued);
        app.quantized_bar = Some(0);
        app.mod_matrix.midi_learn = Some(2);
        app.ntsc_presented = Some((7, vec![255; 4]));
        app.selective_transition_holding = true;
        app.selective_hold_snapshot_valid = true;
        app.selective_hold_spout_barrier_epoch = Some(11);
        app.selective_hold_spout_readback_epoch = Some(11);
        app.blackout = true;
        app.blackout_presented = false;
        let old_stack_revision = app.layer_stack_revision;
        let old_visual_epoch = app.visual_epoch;

        app.reset_patch_generation();

        assert!(app.quantized_actions.is_empty());
        assert!(app.mod_matrix.midi_learn.is_none());
        assert_eq!(app.mod_matrix.current_beat, 9.25);
        assert_eq!(app.mod_matrix.clock.beat(clock_probe), clock_beat_before);
        assert!(app.web_state.actions.blocking_lock().is_empty());
        assert_eq!(app.quantized_bar, Some(2));
        assert!(app.ntsc_presented.is_none());
        assert!(!app.selective_transition_holding);
        assert!(!app.selective_hold_snapshot_valid);
        assert!(app.selective_hold_spout_barrier_epoch.is_none());
        assert!(app.selective_hold_spout_readback_epoch.is_none());
        assert!(app.blackout_presented);
        assert_ne!(app.layer_stack_revision, old_stack_revision);
        assert_ne!(app.visual_epoch, old_visual_epoch);

        // The first post-commit frame observes zero elapsed modulation time,
        // regardless of how long patch reconstruction took.
        app.mod_matrix
            .update(timing_anchor + Duration::from_secs(30));
        assert_eq!(app.mod_matrix.pad, [1.0, 0.0]);
    }

    #[test]
    fn snapshot_audio_decode_failure_is_atomic_and_success_commits_a_ready_clip() {
        fn mono_pcm16_wav(sample_count: usize) -> Vec<u8> {
            let data_bytes = u32::try_from(sample_count * 2).unwrap();
            let mut wav = Vec::with_capacity(44 + data_bytes as usize);
            wav.extend_from_slice(b"RIFF");
            wav.extend_from_slice(&(36 + data_bytes).to_le_bytes());
            wav.extend_from_slice(b"WAVEfmt ");
            wav.extend_from_slice(&16_u32.to_le_bytes());
            wav.extend_from_slice(&1_u16.to_le_bytes());
            wav.extend_from_slice(&1_u16.to_le_bytes());
            wav.extend_from_slice(&48_000_u32.to_le_bytes());
            wav.extend_from_slice(&96_000_u32.to_le_bytes());
            wav.extend_from_slice(&2_u16.to_le_bytes());
            wav.extend_from_slice(&16_u16.to_le_bytes());
            wav.extend_from_slice(b"data");
            wav.extend_from_slice(&data_bytes.to_le_bytes());
            wav.resize(44 + data_bytes as usize, 0);
            wav
        }

        let unique = format!(
            "collide-o-scope-snapshot-audio-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("system time")
                .as_nanos()
        );
        let folder = std::env::temp_dir().join(unique);
        std::fs::create_dir_all(&folder).expect("create snapshot fixture folder");
        let corrupt_path = folder.join("corrupt.wav");
        let valid_path = folder.join("ready.wav");
        std::fs::write(&corrupt_path, b"not a wave file").expect("write corrupt audio fixture");
        std::fs::write(&valid_path, mono_pcm16_wav(2048)).expect("write valid audio fixture");

        let web_state = WebState::new().expect("test token");
        let mut app = App::new(None, None, web_state);
        app.master_effects.brightness = 0.25;
        app.mod_matrix.audio_clip_path = "pre-existing.wav".to_string();
        let original_visual_epoch = app.visual_epoch;
        let original_stack_revision = app.layer_stack_revision;

        let mut corrupt_patch = app.capture_current_patch();
        corrupt_patch.master.brightness = 0.9;
        let corrupt_modulation = corrupt_patch
            .modulation
            .as_mut()
            .expect("captured modulation");
        corrupt_modulation.audio_enabled = true;
        corrupt_modulation.audio_source_kind = modulation::AUDIO_SOURCE_FILE.to_string();
        corrupt_modulation.audio_clip_path = "corrupt.wav".to_string();
        let patch_path = folder.join("snapshot.yaml");

        let mut missing_patch = corrupt_patch.clone();
        missing_patch
            .modulation
            .as_mut()
            .expect("captured modulation")
            .audio_clip_path = "missing.wav".to_string();
        let error = app
            .apply_loaded_patch(missing_patch, &patch_path)
            .expect_err("missing imported audio must reject the whole snapshot");
        assert!(
            error.contains("analysis audio"),
            "unexpected error: {error}"
        );
        assert_eq!(app.master_effects.brightness, 0.25);
        assert_eq!(app.mod_matrix.audio_clip_path, "pre-existing.wav");
        assert_eq!(app.visual_epoch, original_visual_epoch);
        assert_eq!(app.layer_stack_revision, original_stack_revision);

        let error = app
            .apply_loaded_patch(corrupt_patch.clone(), &patch_path)
            .expect_err("corrupt imported audio must reject the whole snapshot");
        assert!(
            error.contains("analysis audio"),
            "unexpected error: {error}"
        );
        assert_eq!(app.master_effects.brightness, 0.25);
        assert_eq!(app.mod_matrix.audio_clip_path, "pre-existing.wav");
        assert_eq!(app.visual_epoch, original_visual_epoch);
        assert_eq!(app.layer_stack_revision, original_stack_revision);

        let mut valid_patch = corrupt_patch;
        valid_patch
            .modulation
            .as_mut()
            .expect("captured modulation")
            .audio_clip_path = "ready.wav".to_string();
        app.apply_loaded_patch(valid_patch, &patch_path)
            .expect("fully staged snapshot");

        assert_eq!(app.master_effects.brightness, 0.9);
        let expected_path = valid_path.canonicalize().expect("canonical fixture path");
        assert_eq!(
            PathBuf::from(&app.mod_matrix.audio_clip_path)
                .canonicalize()
                .expect("canonical committed path"),
            expected_path
        );
        assert_eq!(
            PathBuf::from(
                &app.audio_clip
                    .as_ref()
                    .expect("decoded clip committed")
                    .info()
                    .path
            )
            .canonicalize()
            .expect("canonical decoded clip path"),
            expected_path
        );
        assert_eq!(
            app.audio_clip_loader.state(),
            audio::AudioClipLoadState::Idle
        );
        assert!(!app.audio_clip_blocks_program);

        let mut fingerprints =
            media_source::FingerprintSession::new(media_source::FingerprintLimits::default())
                .expect("fingerprint session");
        let content_reference = fingerprints
            .fingerprint(&valid_path)
            .expect("fingerprint valid analysis clip")
            .source_reference();
        let mut content_patch = app.capture_current_patch();
        content_patch
            .modulation
            .as_mut()
            .expect("captured modulation")
            .audio_clip_path = content_reference.clone();
        app.apply_loaded_patch(content_patch, &patch_path)
            .expect("load content-addressed analysis clip");

        assert_eq!(
            PathBuf::from(&app.mod_matrix.audio_clip_path)
                .canonicalize()
                .expect("resolved runtime analysis path"),
            expected_path
        );
        assert_eq!(
            app.mod_matrix.audio_clip_source_reference.as_deref(),
            Some(content_reference.as_str())
        );
        assert_eq!(
            app.capture_current_patch()
                .modulation
                .expect("recaptured modulation")
                .audio_clip_path,
            content_reference,
            "exact load -> runtime -> capture must retain the content identity"
        );

        std::fs::remove_dir_all(folder).expect("remove snapshot fixture folder");
    }

    #[test]
    fn curated_blend_actions_share_exact_parsing_morph_validation_and_look_conflicts() {
        use web::state::WebAction;

        for expected in layers::BlendMode::ALL {
            let value = serde_json::json!(expected.key());
            assert_eq!(App::blend_mode_edit(&value), Some(expected));
            assert_eq!(
                App::layer_param_morph_control("blend_mode", &value),
                Some(morph::LayerMorphControl::BlendMode)
            );

            let action = WebAction::SetLayerParam {
                index: 0,
                layer_id: Some("17".to_string()),
                param: "blend_mode".to_string(),
                value,
            };
            assert!(App::action_conflicts_with_applied_look(
                &action,
                &legacy_look_scope(vec![17], false, false),
            ));
            assert!(!App::action_conflicts_with_applied_look(
                &action,
                &legacy_look_scope(vec![18], false, false),
            ));
        }

        for invalid in [
            serde_json::json!("soft-light"),
            serde_json::json!("Alpha Cut"),
            serde_json::json!("future_blend"),
            serde_json::json!(14),
            serde_json::Value::Null,
        ] {
            assert_eq!(App::blend_mode_edit(&invalid), None);
            assert_eq!(App::layer_param_morph_control("blend_mode", &invalid), None);
        }
    }

